/** @module agent-protocol/acp/constants
 * Protocol version, timeout defaults, artifact-detection patterns, and
 * model-config identifier sets used across all acp/ files. No dependencies
 * on other agent-protocol modules — safe to import from anywhere in acp/.
 */

/** ACP JSON-RPC protocol version sent in every `initialize` handshake. */
export const ACP_PROTOCOL_VERSION = 1;
/** Default timeout in milliseconds for short-lived ACP operations such as model detection. */
export const DEFAULT_TIMEOUT_MS = 15_000;
/** Absolute upper ceiling for any ACP-derived timeout value (24 hours). */
export const MAX_TIMEOUT_MS = 24 * 60 * 60 * 1000;
// Gap-between-chunks watchdog for an ACP session stage. The timer resets on
// every line received from the agent, so this bounds *silent* periods, not
// total runtime. Default kept in line with the outer chat-run inactivity
// watchdog (10 min) so agents that spend several minutes silently writing
// large artifacts do not get killed before the outer watchdog can apply.
// Callers can override via `stageTimeoutMs`; the chat server reads
// `OD_ACP_STAGE_TIMEOUT_MS` from the environment.
// A non-positive `stageTimeoutMs` (`<= 0`) disables the watchdog entirely,
// mirroring the outer chat watchdog's escape-hatch semantics — without this,
// `OD_ACP_STAGE_TIMEOUT_MS=0` would call `setTimeout(..., 0)` and fail every
// ACP session on the next tick instead of disabling the watchdog.
/** Default per-stage inactivity watchdog timeout (10 minutes) for an ACP session; resets on every received line from the agent subprocess. */
export const DEFAULT_STAGE_TIMEOUT_MS = 10 * 60 * 1000;
/** Regex source fragment matching an opening DSML artifact or plain `artifact` tag in an ACP agent's text output. */
export const ACP_ARTIFACT_OPEN_PATTERN = String.raw`<\s*(?:\|?\s*DSML[\s,]+artifact\b|artifact\b)`;
/** Regex source fragment matching agent preamble text like "here is the generated file:" that precedes an artifact open tag. */
export const ACP_GENERATED_FILE_PREFIX_PATTERN =
  String.raw`(?:here\s+is|here'?s)\s+the\s+generated\s+file\s*:?\s*(?:\r?\n|\s)*`;
/** Compiled regex that detects the start of an ACP artifact echo in an `agent_message_chunk` delta; used to arm the DSML text suppressor. */
export const ACP_ARTIFACT_ECHO_START_RE = new RegExp(
  String.raw`^\s*(?:${ACP_ARTIFACT_OPEN_PATTERN}|${ACP_GENERATED_FILE_PREFIX_PATTERN}${ACP_ARTIFACT_OPEN_PATTERN})`,
  'i',
);
/** Maximum number of `acp_raw_event_shape` and `acp_artifact_text_suppression` diagnostic events emitted per session to avoid flooding the event stream. */
export const ACP_RAW_EVENT_SHAPE_DIAGNOSTIC_LIMIT = 8;
/** Maximum number of bytes retained from stderr to detect AMR retry/failure signals; older bytes are discarded to bound memory use. */
export const AMR_STDERR_RETRY_TAIL_LIMIT = 16_000;
/** Normalised token IDs that identify a model-selection config option in an ACP `session/new` response's `configOptions` array. */
export const MODEL_CONFIG_OPTION_IDS = new Set(['model', 'models', 'modelid', 'modelids']);

/** @module agent-protocol/acp
 * Public barrel for the ACP (Agent Client Protocol) JSON-RPC subprocess
 * transport. Re-exports the surface consumed by runtime adapter definitions
 * (detectAcpModels, normalizeModels, ModelOption) and the daemon's
 * connection-test and chat-server entry points (attachAcpSession,
 * buildAcpSessionNewParams, AcpMcpServerInput).
 */
export { type AcpMcpServerInput, buildAcpSessionNewParams } from './session-params.js';
export { type ModelOption, normalizeModels, detectAcpModels } from './models.js';
export { attachAcpSession } from './session.js';

/** @module agent-protocol/acp/json
 * Pure JSON value-extraction and text-traversal helpers for the ACP layer,
 * plus the `OD_ACP_TIMEOUT_MS` environment resolver. Has no side effects and
 * performs no I/O; depends only on acp/types and acp/constants.
 * Consumed by acp/rpc.ts, acp/session.ts, acp/models.ts, and acp/updates.ts.
 */
import type { JsonObject } from './types.js';
import { MAX_TIMEOUT_MS } from './constants.js';

/**
 * Extracts a human-readable error message from an unknown thrown value.
 * Returns `err.message` for `Error` instances, `String(err)` otherwise.
 *
 * @param err - Any caught value (typically an `Error` but may be anything).
 */
export function errorMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}
/**
 * Resolves the effective ACP timeout from `OD_ACP_TIMEOUT_MS` in the process
 * environment, falling back to `fallbackMs` when the variable is absent or
 * non-finite. Clamps the result to `[0, MAX_TIMEOUT_MS]`.
 *
 * @param env - The process environment object to read `OD_ACP_TIMEOUT_MS` from.
 * @param fallbackMs - The default timeout to use when the env var is unset.
 * @returns The resolved timeout in milliseconds.
 */
export function resolveAcpTimeoutMs(env: NodeJS.ProcessEnv, fallbackMs: number): number {
  const raw = Number(env.OD_ACP_TIMEOUT_MS);
  if (!Number.isFinite(raw)) return fallbackMs;
  return Math.min(MAX_TIMEOUT_MS, Math.max(0, Math.floor(raw)));
}
/**
 * Coerces an unknown value to a `JsonObject` if it is a non-null, non-array
 * plain object, or returns `null` otherwise. The primary guard used throughout
 * the ACP layer before accessing named properties on parsed JSON frames.
 *
 * @param value - Any value from a JSON parse result.
 * @returns The value cast as `JsonObject`, or `null` when the cast is unsafe.
 */
export function asObject(value: unknown): JsonObject | null {
  return value && typeof value === 'object' ? value as JsonObject : null;
}
/**
 * Returns a short diagnostic string describing the JSON kind of `value`:
 * `'array'`, `'null'`, or the result of `typeof`. Used to build
 * `acp_raw_event_shape` diagnostics without touching the value.
 *
 * @param value - Any value from a parsed ACP update object.
 */
export function acpValueKind(value: unknown): string {
  if (Array.isArray(value)) return 'array';
  if (value === null) return 'null';
  return typeof value;
}
/**
 * Returns a sorted array of own string keys from `value` if it is a
 * `JsonObject`, or an empty array otherwise. Used to snapshot object
 * structure for diagnostic payloads without risking a throw.
 *
 * @param value - Any value from a parsed ACP update object.
 */
export function objectKeys(value: unknown): string[] {
  const obj = asObject(value);
  return obj ? Object.keys(obj).sort() : [];
}
/**
 * Recursively traverses an ACP update value up to 4 levels deep and returns
 * the first non-empty string found, checking common text-bearing keys in order:
 * `text`, `delta`, `content`, `message`, `output`, `answer`, `value`, `body`,
 * `parts`, `choices`. Handles string scalars, flat arrays, and nested objects.
 *
 * Used as the extraction primitive by `extractAcpUpdateText`.
 *
 * @param value - A value from a parsed ACP session update.
 * @param depth - Current recursion depth (max 4); callers omit this.
 * @returns The first non-empty string found, or `null` when none is present.
 */
export function extractAcpTextValue(value: unknown, depth = 0): string | null {
  if (depth > 4) return null;
  if (typeof value === 'string') return value.length > 0 ? value : null;
  if (Array.isArray(value)) {
    const text = value
      .map((item) => extractAcpTextValue(item, depth + 1))
      .filter((part): part is string => typeof part === 'string' && part.length > 0)
      .join('');
    return text.length > 0 ? text : null;
  }
  const obj = asObject(value);
  if (!obj) return null;
  for (const key of [
    'text',
    'delta',
    'content',
    'message',
    'output',
    'answer',
    'value',
    'body',
    'parts',
    'choices',
  ]) {
    const text = extractAcpTextValue(obj[key], depth + 1);
    if (text) return text;
  }
  return null;
}
/**
 * Extracts the first non-empty text string from the top-level properties of a
 * parsed ACP session update object. Checks the same key list as
 * `extractAcpTextValue` but at only one level of depth (the update object
 * itself), delegating deep traversal to that helper.
 *
 * @param update - A parsed ACP `session/update` params object.
 * @returns The first non-empty text string, or `null` when none is present.
 */
export function extractAcpUpdateText(update: JsonObject): string | null {
  for (const key of [
    'content',
    'text',
    'delta',
    'message',
    'output',
    'answer',
    'value',
    'body',
    'parts',
    'choices',
  ]) {
    const text = extractAcpTextValue(update[key]);
    if (text) return text;
  }
  return null;
}

/**
 * Pull a short human-readable status detail (`message` / `detail`) off an ACP
 * `session/update`, so a status event can carry e.g. a "compacting context"
 * reason. Returns `undefined` when neither field is a non-empty string.
 */
export function extractAcpStatusDetail(update: JsonObject): string | undefined {
  for (const key of ['message', 'detail']) {
    const value = update[key];
    if (typeof value === 'string' && value.trim()) return value;
  }
  return undefined;
}

/** @module agent-protocol/acp/models
 * ACP model detection, normalisation, and config-option selection. The primary
 * export `detectAcpModels` spawns an ACP subprocess, performs the
 * `initialize` + `session/new` handshake, and returns the available model list.
 * Consumed by runtime adapter definitions (runtimes/defs/shared.ts). Depends
 * on the core JSON-line stream and acp/types, acp/constants, acp/json,
 * acp/rpc, and acp/session-params.
 */
import { spawn } from 'node:child_process';
import { createJsonLineStream } from '../core/index.js';
import type { JsonRpcId, JsonObject, TimerHandle } from './types.js';
import { ACP_PROTOCOL_VERSION, DEFAULT_TIMEOUT_MS, MODEL_CONFIG_OPTION_IDS } from './constants.js';
import { errorMessage, resolveAcpTimeoutMs, asObject } from './json.js';
import { sendRpc, rpcErrorMessage } from './rpc.js';
import { buildAcpSessionNewParams } from './session-params.js';

/** A single model entry exposed to the daemon's model-selection UI and to `session/set_model` calls. */
export interface ModelOption {
  id: string;
  label: string;
}
/** Parsed model-selection config option extracted from an ACP `session/new` result's `configOptions` array. */
export interface AcpModelConfigOption {
  configId: string;
  currentValue: string | null;
  values: unknown[];
}
/** Options accepted by `detectAcpModels` to control how the probe subprocess is launched and identified. */
export interface DetectAcpModelsOptions {
  bin: string;
  args: string[];
  cwd?: string;
  env?: NodeJS.ProcessEnv;
  timeoutMs?: number;
  clientName?: string;
  clientVersion?: string;
  defaultModelOption?: ModelOption;
}
/**
 * Normalises a raw config-option field value to a lowercase, whitespace- and
 * punctuation-stripped token for fuzzy matching against `MODEL_CONFIG_OPTION_IDS`.
 *
 * @param value - A raw field value from an ACP config option object.
 * @returns A normalised token string, or `''` when `value` is not a string.
 */
export function normalizeConfigOptionToken(value: unknown): string {
  return typeof value === 'string'
    ? value.trim().toLowerCase().replace(/[\s_-]+/g, '')
    : '';
}
/**
 * Returns `true` when the given `option` object from `configOptions` represents
 * a model-selection config option, using a cascade of category, id, and name
 * normalisation checks against `MODEL_CONFIG_OPTION_IDS`.
 *
 * @param option - A single item from the `configOptions` array.
 * @param configId - The trimmed `id` field of that item.
 */
export function isModelConfigOption(option: JsonObject, configId: string): boolean {
  const category = normalizeConfigOptionToken(option.category);
  if (category === 'model') return true;
  const id = normalizeConfigOptionToken(configId);
  if (id === 'model') return true;
  if (category) return false;
  const name = normalizeConfigOptionToken(option.name);
  return MODEL_CONFIG_OPTION_IDS.has(id) || name === 'model';
}
/**
 * Scans the `configOptions` array from an ACP `session/new` result and returns
 * the first entry that passes `isModelConfigOption`. Returns `null` when no
 * model config option is found, so callers can fall back to the `models` field.
 *
 * @param configOptions - The raw `result.configOptions` value from a session response.
 * @returns A parsed `AcpModelConfigOption` or `null` when absent.
 */
export function findModelConfigOption(configOptions: unknown): AcpModelConfigOption | null {
  const options = Array.isArray(configOptions) ? configOptions : [];
  for (const rawOption of options) {
    const option = asObject(rawOption);
    if (!option) continue;
    const configId = typeof option.id === 'string' ? option.id.trim() : '';
    if (!configId) continue;
    const type = typeof option.type === 'string' ? option.type.trim() : '';
    if (type && type !== 'select') continue;
    if (!isModelConfigOption(option, configId)) continue;
    const currentValue =
      typeof option.currentValue === 'string' && option.currentValue.trim()
        ? option.currentValue.trim()
        : null;
    return {
      configId,
      currentValue,
      values: Array.isArray(option.options) ? option.options : [],
    };
  }
  return null;
}
/**
 * Extracts and normalises the available models list from an ACP
 * `configOptions` array (preferred) into a `ModelOption[]`. Prepends
 * `defaultModelOption` and deduplicates by id. Returns `null` when no model
 * config option is found in `configOptions`.
 *
 * @param configOptions - The raw `result.configOptions` from a session response.
 * @param defaultModelOption - The fallback option to prepend to the list.
 * @returns `{ currentModelId, models }` or `null` when no config option is found.
 */
export function normalizeModelConfigOptions(
  configOptions: unknown,
  defaultModelOption: ModelOption,
): { currentModelId: string | null; models: ModelOption[] } | null {
  const modelConfig = findModelConfigOption(configOptions);
  if (!modelConfig) return null;
  const seen = new Set([defaultModelOption.id]);
  const out = [defaultModelOption];
  for (const rawValue of modelConfig.values) {
    const value = asObject(rawValue);
    if (!value) continue;
    const id =
      typeof value.value === 'string' && value.value.trim()
        ? value.value.trim()
        : typeof value.id === 'string'
          ? value.id.trim()
          : '';
    if (!id || seen.has(id)) continue;
    seen.add(id);
    const name = typeof value.name === 'string' ? value.name.trim() : '';
    const isCurrent = id === modelConfig.currentValue;
    const labelBase = name && name !== id ? `${name} (${id})` : id;
    out.push({ id, label: isCurrent ? `${labelBase} • current` : labelBase });
  }
  return { currentModelId: modelConfig.currentValue, models: out };
}
/**
 * Produces the final ordered `ModelOption[]` for a session, merging the
 * `configOptions` path (preferred when it yields more than one option) with
 * the legacy `models.availableModels` path. Always includes `defaultModelOption`
 * at position zero and deduplicates by id.
 *
 * @param models - The raw `result.models` value from a `session/new` response.
 * @param defaultModelOption - The fallback option to prepend.
 * @param configOptions - Optional `result.configOptions` for the config-option path.
 * @returns A deduplicated array of `ModelOption` items.
 */
export function normalizeModels(
  models: unknown,
  defaultModelOption: ModelOption,
  configOptions?: unknown,
): ModelOption[] {
  const configModels = normalizeModelConfigOptions(configOptions, defaultModelOption);
  if (configModels && configModels.models.length > 1) {
    return configModels.models;
  }
  const modelsObj = asObject(models);
  const available = Array.isArray(modelsObj?.availableModels) ? modelsObj.availableModels : [];
  const currentModelId =
    typeof modelsObj?.currentModelId === 'string' ? modelsObj.currentModelId : null;
  const seen = new Set([defaultModelOption.id]);
  const out = [defaultModelOption];
  for (const model of available) {
    const id = typeof model?.modelId === 'string' ? model.modelId.trim() : '';
    if (!id || seen.has(id)) continue;
    seen.add(id);
    const name = typeof model?.name === 'string' ? model.name.trim() : '';
    const isCurrent = id === currentModelId;
    const labelBase = name && name !== id ? `${name} (${id})` : id;
    out.push({ id, label: isCurrent ? `${labelBase} • current` : labelBase });
  }
  return out.length > 1 || !configModels ? out : configModels.models;
}
/**
 * Returns `true` for JSON-RPC error codes that indicate a model-selection
 * failure from which the session can recover by falling back to the default
 * model and sending the prompt anyway.
 *
 * @param code - The `error.code` value from a JSON-RPC error response.
 */
export function modelSelectionErrorIsRecoverable(code: unknown): boolean {
  return code === -32603 || code === -32602 || code === -32601 || code === -32002;
}
/**
 * Reads the currently active model id from a `session/new` (or
 * `session/set_model`) result object, checking `configOptions` first and
 * falling back to `models.currentModelId`. Returns `null` when neither is set.
 *
 * @param result - The parsed `result` object from a session handshake response.
 */
export function currentModelFromSessionResult(result: JsonObject): string | null {
  const configCurrent = findModelConfigOption(result.configOptions)?.currentValue;
  if (configCurrent) return configCurrent;
  const models = asObject(result.models);
  return typeof models?.currentModelId === 'string' && models.currentModelId.trim()
    ? models.currentModelId.trim()
    : null;
}
/**
 * Probes a running ACP binary by spawning it, performing the
 * `initialize` → `session/new` handshake, and reading the model list from the
 * session result. The child is killed with `SIGTERM` once the list is
 * extracted or the timeout expires.
 *
 * Used by runtime adapter definitions to populate the model-selection dropdown
 * without waiting for an actual prompt run.
 *
 * @param options.bin - Absolute path or `$PATH`-resolvable name of the ACP binary.
 * @param options.args - CLI arguments to pass to the binary.
 * @param options.cwd - Working directory for the probe subprocess.
 * @param options.env - Environment for the probe subprocess (default: `process.env`).
 * @param options.timeoutMs - Hard timeout for the probe; subject to `MAX_TIMEOUT_MS`.
 * @param options.clientName - Client name sent in the `initialize` handshake.
 * @param options.clientVersion - Client version sent in the `initialize` handshake.
 * @param options.defaultModelOption - Fallback option prepended to the result list.
 * @returns A promise resolving to the available `ModelOption[]`.
 */
export async function detectAcpModels({
  bin,
  args,
  cwd = process.cwd(),
  env = process.env,
  timeoutMs = DEFAULT_TIMEOUT_MS,
  clientName = 'open-design-detect',
  clientVersion = 'runtime-adapter',
  defaultModelOption = { id: 'default', label: 'Default (CLI config)' },
}: DetectAcpModelsOptions): Promise<ModelOption[]> {
  const effectiveTimeoutMs = resolveAcpTimeoutMs(env, timeoutMs);
  return await new Promise<ModelOption[]>((resolve, reject) => {
    const child = spawn(bin, args, {
      cwd,
      stdio: ['pipe', 'pipe', 'pipe'],
      env: { ...env },
    });
    child.stdout.setEncoding('utf8');
    child.stderr.setEncoding('utf8');

    let settled = false;
    let stderrBuf = '';
    let expectedId = 1;
    let nextId = 2;

    let timer: TimerHandle | null = null;
    const finish = <T extends ModelOption[] | Error>(fn: (value: T) => void, value: T) => {
      if (settled) return;
      settled = true;
      if (timer) clearTimeout(timer);
      try {
        child.stdin.end();
      } catch {}
      fn(value);
    };

    const fail = (message: string) => {
      finish(reject, new Error(message));
      if (!child.killed) child.kill('SIGTERM');
    };

    const writeRpc = (id: JsonRpcId, method: string, params: unknown) => {
      try {
        sendRpc(child.stdin, id, method, params);
      } catch (err) {
        fail(`stdin write failed: ${errorMessage(err)}`);
      }
    };

    const sendSessionNew = () => {
      expectedId = nextId;
      writeRpc(nextId, 'session/new', buildAcpSessionNewParams(cwd));
      nextId += 1;
    };

    const parser = createJsonLineStream((raw) => {
      const obj = asObject(raw);
      const error = asObject(obj?.error);
      const result = asObject(obj?.result);
      const rpcErr = rpcErrorMessage(raw);
      if (rpcErr) {
        // JSON-RPC -32603 "Internal error" during model detection:
        // If this is for the current expected-id (initialize/session/new),
        // it's a real probe failure — reject immediately.
        // Otherwise it's cleanup noise — suppress it.
        if (error?.code === -32603 && obj?.id !== expectedId) return;
        fail(rpcErr);
        return;
      }
      if (obj?.id !== expectedId || !result) return;
      if (expectedId === 1) {
        sendSessionNew();
        return;
      }
      if (expectedId === 2) {
        const models = normalizeModels(result.models, defaultModelOption, result.configOptions);
        finish(resolve, models);
        if (!child.killed) child.kill('SIGTERM');
      }
    });

    child.stdout.on('data', (chunk) => parser.feed(chunk));
    child.stdout.on('close', () => parser.flush());
    child.stdin.on('error', (err) => fail(`stdin error: ${err.message}`));
    child.stderr.on('data', (chunk) => {
      stderrBuf = `${stderrBuf}${chunk}`.slice(-16_000);
    });
    child.on('error', (err) => fail(`spawn failed: ${err.message}`));
    child.on('close', (code, signal) => {
      parser.flush();
      if (!settled) {
        const errTail = stderrBuf.trim();
        const suffix = errTail ? ` stderr=${errTail}` : '';
        fail(`ACP model detection exited code=${code} signal=${signal ?? 'none'}${suffix}`);
      }
    });

    if (effectiveTimeoutMs > 0) {
      timer = setTimeout(() => {
        fail(`ACP model detection timed out after ${effectiveTimeoutMs}ms`);
      }, effectiveTimeoutMs);
    }

    writeRpc(1, 'initialize', {
      protocolVersion: ACP_PROTOCOL_VERSION,
      clientCapabilities: { terminal: false },
      clientInfo: { name: clientName, version: clientVersion },
    });
  });
}

/** @module agent-protocol/acp/rpc
 * JSON-RPC 2.0 send helpers, error-shape parsers, usage normaliser, and
 * permission-outcome selector for the ACP protocol layer. Depends on
 * acp/types and acp/json; consumed by acp/session.ts and acp/models.ts.
 */
import type { JsonRpcId, RpcWritable } from './types.js';
import { asObject } from './json.js';

/**
 * Writes a JSON-RPC 2.0 request frame to `writable` as a single newline-terminated
 * line. Used to send ACP method calls (e.g. `initialize`, `session/new`,
 * `session/prompt`) to an agent subprocess's stdin.
 *
 * @param writable - The agent's stdin (or equivalent writable).
 * @param id - The JSON-RPC request id used to correlate the response.
 * @param method - The RPC method name.
 * @param params - The method parameter payload (any JSON-serialisable value).
 */
export function sendRpc(writable: RpcWritable, id: JsonRpcId, method: string, params: unknown): void {
  writable.write(
    `${JSON.stringify({ jsonrpc: '2.0', id, method, params })}\n`,
  );
}
/**
 * Writes a JSON-RPC 2.0 result response frame to `writable`. Used to reply to
 * incoming `session/request_permission` calls from an ACP agent.
 *
 * @param writable - The agent's stdin (or equivalent writable).
 * @param id - The id from the incoming request being answered.
 * @param result - The result payload to include in the response.
 */
export function sendRpcResult(writable: RpcWritable, id: JsonRpcId, result: unknown): void {
  writable.write(`${JSON.stringify({ jsonrpc: '2.0', id, result })}\n`);
}
/**
 * Type guard that returns `true` when `value` is a valid JSON-RPC id
 * (a `number` or `string`). Used before replying to incoming requests.
 */
export function isJsonRpcId(value: unknown): value is JsonRpcId {
  return typeof value === 'number' || typeof value === 'string';
}
/**
 * Extracts a human-readable error message from a raw JSON-RPC response object
 * that contains an `error` field. Returns an empty string when the response
 * is not an error frame, allowing callers to use it as a truthy check.
 *
 * @param raw - A parsed JSON-RPC response object (unknown shape).
 * @returns A non-empty error message string, or `''` when not an error response.
 */
export function rpcErrorMessage(raw: unknown): string {
  const obj = asObject(raw);
  const error = asObject(obj?.error);
  if (!obj || !error) {
    return '';
  }
  const message =
    typeof error.message === 'string'
      ? error.message
      : typeof error.code === 'number'
        ? String(error.code)
        : 'json-rpc error';
  return typeof obj.id === 'number'
    ? `json-rpc id ${obj.id}: ${message}`
    : message;
}
/**
 * Extracts the structured `data` field from a JSON-RPC error response's `error`
 * object, if present. Used to retrieve typed failure details (e.g. `retryable`,
 * vendor-specific error codes) without throwing.
 *
 * @param raw - A parsed JSON-RPC response object (unknown shape).
 * @returns The `error.data` value, or `undefined` when absent.
 */
export function rpcErrorData(raw: unknown): unknown {
  const obj = asObject(raw);
  const error = asObject(obj?.error);
  return error && 'data' in error ? error.data : undefined;
}
/**
 * Reads the `retryable` boolean from a structured RPC error `data` payload.
 * Returns `undefined` when the field is absent so callers can distinguish
 * "explicitly false" from "not present" and apply their own default.
 *
 * @param data - The value of `error.data` extracted via `rpcErrorData`.
 */
export function rpcErrorRetryable(data: unknown): boolean | undefined {
  const details = asObject(data);
  return typeof details?.retryable === 'boolean' ? details.retryable : undefined;
}
/**
 * Fallback retryability inference from the error message/details text, used when
 * the runtime does not set an explicit `retryable` field. `request_too_large`
 * (the prompt must shrink) is non-retryable; upstream transport blips
 * (`stream idle timeout`, `overloaded`, gateway/service outages) are retryable.
 * Returns `undefined` when nothing matches so callers keep their own default.
 */
export function inferRpcErrorRetryable(message: string, data: unknown): boolean | undefined {
  const details = asObject(data);
  const text = [
    message,
    details ? JSON.stringify(details) : '',
  ].join('\n');
  if (/\b(request_too_large|request body exceeds configured limit)\b/i.test(text)) {
    return false;
  }
  if (/\b(upstream_error|stream idle timeout|no data received within configured window|temporarily unavailable|overloaded|gateway timeout|service unavailable)\b/i.test(text)) {
    return true;
  }
  return undefined;
}
/**
 * Promotes an opencode `ROLE_MARKER_HALLUCINATION` error embedded in an ACP
 * JSON-RPC `error.data` payload into a canonical OpenDesign error object.
 * Returns `null` when the data payload does not match the expected shape.
 * Exists so callers can surface a vendor-specific failure with a structured
 * error code rather than a bare generic message.
 *
 * @param data - The `error.data` field from a JSON-RPC error response.
 * @param fallbackMessage - Used when the payload's `message` field is blank.
 * @returns A structured error payload, or `null` when not applicable.
 */
export function promotedOpenCodeSessionErrorPayload(data: unknown, fallbackMessage: string) {
  const details = asObject(data);
  if (
    details?.kind !== 'opencode_session_error' ||
    details.source !== 'opencode' ||
    details.code !== 'ROLE_MARKER_HALLUCINATION'
  ) {
    return null;
  }
  const message =
    typeof details.message === 'string' && details.message.trim()
      ? details.message.trim()
      : fallbackMessage;
  return {
    message,
    error: {
      code: 'ROLE_MARKER_HALLUCINATION',
      message,
      retryable: typeof details.retryable === 'boolean' ? details.retryable : true,
      details: {
        ...details,
        promoted_by: 'open_design_acp',
      },
    },
  };
}
/** Normalised token-usage counters extracted from an ACP session result for downstream analytics and cost tracking. */
export interface FormattedUsage {
  input_tokens?: number;
  output_tokens?: number;
  /** OpenAI-like inclusive cache-read subset (input already includes cache). */
  cached_read_tokens?: number;
  /** Anthropic-like additive cache-read (input is uncached remainder). */
  cache_read_input_tokens?: number;
  /** Generic / OpenAI-like cache write alias. */
  cache_creation_tokens?: number;
  /** Anthropic-like cache creation field name. */
  cache_creation_input_tokens?: number;
  /** OpenAI-like cache write alias used by some ACP adapters. */
  cached_write_tokens?: number;
  thought_tokens?: number;
  total_tokens?: number;
}

function firstFiniteNumber(src: Record<string, unknown>, keys: string[]): number | undefined {
  for (const key of keys) {
    const value = src[key];
    if (typeof value === 'number' && Number.isFinite(value) && value >= 0) {
      return value;
    }
  }
  return undefined;
}

/**
 * Normalises an ACP agent's raw `usage` object (camelCase and/or snake_case
 * keys) into the snake_case `FormattedUsage` shape used by the daemon event
 * stream. Returns `null` when the input is not a recognisable usage object or
 * has no known fields.
 *
 * Cache field names are preserved by family so
 * `scanRunEventsForUsageAnalytics` can classify anthropic (additive) vs
 * openai (inclusive) correctly. Do not collapse Anthropic
 * `cache_read_input_tokens` into `cached_read_tokens`.
 *
 * @param usage - The raw `result.usage` value from a `session/prompt` response.
 * @returns A `FormattedUsage` object with at least one field, or `null`.
 */
export function formatUsage(usage: unknown): FormattedUsage | null {
  const src = asObject(usage);
  if (!src) return null;
  const out: FormattedUsage = {};
  const inputTokens = firstFiniteNumber(src, ['inputTokens', 'input_tokens']);
  const outputTokens = firstFiniteNumber(src, ['outputTokens', 'output_tokens']);
  // Prefer source-family keys independently so mixed payloads keep both
  // semantics when present; otherwise map only within the matching family.
  const anthropicCacheRead = firstFiniteNumber(src, [
    'cache_read_input_tokens',
    'cacheReadInputTokens',
  ]);
  const openAiCacheRead = firstFiniteNumber(src, [
    'cachedReadTokens',
    'cached_read_tokens',
  ]);
  const anthropicCacheCreation = firstFiniteNumber(src, [
    'cache_creation_input_tokens',
    'cacheCreationInputTokens',
  ]);
  const openAiCacheCreation = firstFiniteNumber(src, [
    'cacheCreationTokens',
    'cache_creation_tokens',
  ]);
  const openAiCachedWrite = firstFiniteNumber(src, [
    'cached_write_tokens',
    'cachedWriteTokens',
  ]);
  const thoughtTokens = firstFiniteNumber(src, ['thoughtTokens', 'thought_tokens']);
  const totalTokens = firstFiniteNumber(src, ['totalTokens', 'total_tokens']);
  if (inputTokens !== undefined) out.input_tokens = inputTokens;
  if (outputTokens !== undefined) out.output_tokens = outputTokens;
  if (anthropicCacheRead !== undefined) out.cache_read_input_tokens = anthropicCacheRead;
  if (openAiCacheRead !== undefined) out.cached_read_tokens = openAiCacheRead;
  if (anthropicCacheCreation !== undefined) {
    out.cache_creation_input_tokens = anthropicCacheCreation;
  }
  if (openAiCacheCreation !== undefined) out.cache_creation_tokens = openAiCacheCreation;
  if (openAiCachedWrite !== undefined) out.cached_write_tokens = openAiCachedWrite;
  if (thoughtTokens !== undefined) out.thought_tokens = thoughtTokens;
  if (totalTokens !== undefined) out.total_tokens = totalTokens;
  return Object.keys(out).length > 0 ? out : null;
}
/**
 * Selects the best permission-outcome `optionId` to reply with when an ACP
 * agent sends a `session/request_permission` request. Prefers
 * `approve_for_session`, then `allow_always`, then `allow_once`.
 *
 * @param options - The `params.options` array from the incoming permission request.
 * @returns The chosen `optionId` string, or `null` when no approvable option is found.
 */
export function choosePermissionOutcome(options: unknown): string | null {
  const list = Array.isArray(options) ? options : [];
  const approveForSession = list.find((option) => option?.optionId === 'approve_for_session');
  if (approveForSession) return 'approve_for_session';
  const allowAlways = list.find((option) => option?.kind === 'allow_always');
  if (allowAlways?.optionId) return allowAlways.optionId;
  const allowOnce = list.find((option) => option?.kind === 'allow_once');
  if (allowOnce?.optionId) return allowOnce.optionId;
  return null;
}

/** @module agent-protocol/acp/session-params
 * Builds the `session/new` parameter object and prompt blocks sent to an ACP
 * agent subprocess at session start. Handles MCP server descriptor normalisation
 * and env-format conversion (array vs map). Consumed by acp/session.ts and
 * acp/models.ts; depends only on Node path.
 */
import path from 'node:path';

/**
 * Loose descriptor for a single MCP server entry as supplied by a caller.
 * All fields are typed `unknown` so the builder can safely normalise them
 * without trusting the caller's type discipline.
 */
export interface AcpMcpServerInput {
  type?: unknown;
  name?: unknown;
  command?: unknown;
  args?: unknown;
  env?: unknown;
}
/**
 * Options accepted by `buildAcpSessionNewParams` controlling optional MCP
 * server injection and the env-field wire format used by the target agent.
 */
export interface AcpSessionOptions {
  mcpServers?: AcpMcpServerInput[];
  // How the `env` field of each mcpServer entry is shaped.
  // `'array'` (default) → `[{name, value}]` (Hermes, Kimi, …).
  // `'map'`   → `{"KEY": "val"}` (reasonix 1.x Go, standard MCP).
  envFormat?: 'array' | 'map';
}
/**
 * Builds the params object for an ACP `session/new` JSON-RPC call. Resolves
 * `cwd` to an absolute path and normalises each MCP server entry's `env` field
 * between `'array'` format (`[{name, value}]`, default, used by Hermes/Kimi)
 * and `'map'` format (`{"KEY": "val"}`, used by reasonix and standard MCP).
 *
 * MCP is optional — omit `mcpServers` to run without it. Never auto-installs
 * or mutates user/global MCP config.
 *
 * @param cwd - The working directory to pass to the ACP agent subprocess.
 * @param options - Optional MCP server list and env-format selector.
 * @returns The `session/new` params object ready for JSON-RPC serialisation.
 */
export function buildAcpSessionNewParams(cwd: string, { mcpServers, envFormat = 'array' }: AcpSessionOptions = {}) {
  const servers = Array.isArray(mcpServers) ? mcpServers : [];
  const wantsMap = envFormat === 'map';
  return {
    cwd: path.resolve(cwd),
    // MCP is an optional compatibility layer. Default to no MCP servers so ACP
    // agents can run through the skill + CLI path without MCP support. Do not
    // auto-install or mutate user/global MCP config; callers must pass an
    // explicit per-session MCP descriptor when a compatible agent supports it.
    mcpServers: servers.map((s) => {
      const rawEnv = s?.env;
      // Already a plain object — pass through in map mode, convert to
      // array in array mode (e.g. live-artifacts MCP from
      // buildLiveArtifactsMcpServersForAgent which already respects
      // acpMcpEnvFormat).
      const isPlainObject =
        rawEnv && typeof rawEnv === 'object' && !Array.isArray(rawEnv);
      if (wantsMap && isPlainObject) {
        return {
          type: typeof s?.type === 'string' ? s.type : 'stdio',
          name: typeof s?.name === 'string' ? s.name : '',
          command: typeof s?.command === 'string' ? s.command : '',
          args: Array.isArray(s?.args) ? s.args : [],
          env: rawEnv,
        };
      }
      const envArr = Array.isArray(rawEnv) ? rawEnv : [];
      const env = wantsMap
        ? Object.fromEntries(envArr.map((e: any) => [e?.name ?? '', e?.value ?? '']))
        : isPlainObject
          ? Object.entries(rawEnv as Record<string, string>).map(
              ([name, value]) => ({ name, value }),
            )
          : envArr;
      return {
        type: typeof s?.type === 'string' ? s.type : 'stdio',
        name: typeof s?.name === 'string' ? s.name : '',
        command: typeof s?.command === 'string' ? s.command : '',
        args: Array.isArray(s?.args) ? s.args : [],
        env,
      };
    }),
  };
}
/**
 * Assembles the `prompt` array for a `session/prompt` ACP call. Always
 * includes a leading `{ type: 'text', text: prompt }` block, followed by
 * one `{ type: 'resource_link', uri: imagePath }` block per non-empty image
 * path. Empty or non-string paths are silently skipped.
 *
 * @param prompt - The text prompt to send as the first block.
 * @param imagePaths - Optional image attachment paths to append.
 * @returns An array of prompt blocks ready for inclusion in `session/prompt` params.
 */
export function buildPromptBlocks(prompt: string, imagePaths: string[]): Array<Record<string, string>> {
  const blocks: Array<Record<string, string>> = [{ type: 'text', text: prompt }];
  for (const imagePath of imagePaths) {
    if (typeof imagePath !== 'string' || imagePath.trim().length === 0) continue;
    blocks.push({ type: 'resource_link', uri: imagePath });
  }
  return blocks;
}

/** @module agent-protocol/acp/session
 * ACP session orchestrator: performs the full initialize → session/new (or
 * session/load) → session/prompt handshake with an already-spawned ACP
 * subprocess, streams updates to the daemon event bus, handles permission
 * replies, artifact-write mirroring, DSML text suppression, and clean abort.
 * Depends on every other acp/ file and the core JSON-line stream. Consumed by
 * connectionTest.ts and server.ts (via the acp/ barrel).
 */
import path from 'node:path';
import type { ExecutionProfile } from '@open-design/contracts';
import {
  createDsmlArtifactTextSuppressor,
  createToolCallTextSuppressor,
  type ArtifactTextSuppressor,
