/**
 * Options for `attachAcpSession`. All fields except `child`, `prompt`, and
 * `send` are optional and carry sensible defaults.
 */
export interface AttachAcpSessionOptions {
  child: AcpChildProcess;
  prompt: string;
  cwd?: string;
  model?: string | null;
  imagePaths?: string[];
  mcpServers?: AcpMcpServerInput[];
  // Passed through to buildAcpSessionNewParams — see AcpSessionOptions.
  envFormat?: 'array' | 'map';
  send: (event: string, payload: unknown) => void;
  clientName?: string;
  clientVersion?: string;
  stageTimeoutMs?: number;
  executionProfile?: ExecutionProfile;
  modelUnavailableErrorCode?: 'AMR_MODEL_UNAVAILABLE';
  // Some ACP adapters expose an explicit `turn_end` session update as their
  // terminal turn signal instead of returning the pending session/prompt RPC.
  // Keep this opt-in so standard ACP adapters still require the response.
  completePromptOnTurnEnd?: boolean;
  // When set, resume an existing upstream session instead of creating a new
  // one: the handshake sends `session/load { sessionId }` (the durable handle
  // captured from a prior run via `getDurableSessionId()`) rather than
  // `session/new`. The agent verifies the session and, if it is gone, returns a
  // structured `resume_failed` error the caller maps to its reseed path.
  resumeSessionId?: string | null;
  // Subsegment timing markers for spawn->first-token attribution (#3408 §4).
  // `onCliReady` fires once on the first well-formed ACP JSON-RPC message
  // (the CLI is up and speaking the protocol); `onSessionInit` fires once when
  // the `session/new` handshake is acknowledged (a session id is established).
  // `onPromptComplete` fires once when a clean `session/prompt` result is
  // accepted. Error paths never invoke it.
  onCliReady?: () => void;
  onSessionInit?: () => void;
  onPromptComplete?: () => void;
}
/**
 * Attaches an ACP protocol session to an already-spawned child process and
 * drives the full JSON-RPC conversation from handshake to prompt completion.
 *
 * Sequence:
 * 1. Sends `initialize` to confirm the protocol version.
 * 2. Sends `session/new` (or `session/load` when `resumeSessionId` is set).
 * 3. Optionally sends `session/set_model` when a non-default model is requested.
 * 4. Sends `session/prompt` with the user's prompt and any image attachments.
 * 5. Streams `session/update` events to the `send` callback, translating:
 *    - `agent_thought_chunk` → `thinking_start` / `thinking_delta`
 *    - `agent_message_chunk` → `text_delta` (with DSML and tool-call text suppression)
 *    - `tool_call` / `tool_call_update` → full `tool_use` / `tool_result` transcript
 *      (all tools; write tools keep Claude-shaped names + `file_path` for artifact count)
 *    - status updates → `agent.status` events
 * 6. Handles `session/request_permission` calls by auto-approving.
 * 7. On prompt completion, flushes suppression buffers, emits usage, and closes stdin.
 *
 * Returns a controller object that the caller may use to query session state
 * and to abort the in-progress turn.
 *
 * @param options - See `AttachAcpSessionOptions` for all fields.
 * @returns A controller with `hasFatalError`, `getDurableSessionId`,
 *   `completedSuccessfully`, and `abort` methods.
 */
export function attachAcpSession({
  child,
  prompt,
  cwd,
  model,
  imagePaths = [],
  mcpServers,
  envFormat = 'array',
  send,
  clientName = 'open-design',
  clientVersion = 'runtime-adapter',
  stageTimeoutMs = DEFAULT_STAGE_TIMEOUT_MS,
  executionProfile = 'filesystem',
  modelUnavailableErrorCode,
  completePromptOnTurnEnd = false,
  resumeSessionId,
  onCliReady,
  onSessionInit,
  onPromptComplete,
}: AttachAcpSessionOptions) {
  const runStartedAt = Date.now();
  const effectiveCwd = path.resolve(cwd || process.cwd());
  if (!child.stdin || !child.stdout) {
    throw new Error('ACP child process must expose stdin and stdout streams');
  }
  const stdin = child.stdin;
  const stdout = child.stdout;
  let expectedId = 1;
  let nextId = 2;
  let promptRequestId: JsonRpcId | null = null;
  let setModelRequestId: JsonRpcId | null = null;
  let sessionId: string | null = null;
  // The durable upstream session handle reported by the agent on session/new or
  // session/load (vela's `openCodeSessionId`). The caller stores it per
  // conversation to resume next turn. Distinct from `sessionId`, which is the
  // ACP wrapper id ("vela-opencode-1").
  let durableSessionId: string | null = null;
  let activeModel: string | null = null;
  let modelConfigId: string | null = null;
  let emittedThinkingStart = false;
  let emittedFirstTokenStatus = false;
  let emittedTextChunk = false;
  let emittedVisibleTextChunk = false;
  let emittedToolCall = false;
  let emittedConcreteToolEvent = false;
  let emittedTextBuffer = '';
  let rawAcpShapeDiagnosticCount = 0;
  let artifactSuppressionDiagnosticCount = 0;
  let amrStderrRetryTail = '';
  let finished = false;
  let fatal = false;
  let aborted = false;
  let stageTimer: TimerHandle | null = null;
  let dsmlArtifactSuppressor: ArtifactTextSuppressor | null = null;
  let dsmlArtifactSuppressorLastSuppressedChars = 0;
  let dsmlArtifactSuppressorToolCallId: string | null = null;
  let dsmlArtifactSuppressorArmedAfterText = false;
  let dsmlArtifactSuppressorSawIncrementalProse = false;
  const toolCallTextSuppressor = createToolCallTextSuppressor();
  let toolCallTextSuppressorLastSuppressedChars = 0;
  const artifactTextSuppressionSummary = {
    suppressedChars: 0,
    suppressedChunks: 0,
    openedBlocks: 0,
    closedBlocks: 0,
  };
  const toolCallTextSuppressionSummary = {
    suppressedChars: 0,
    suppressedChunks: 0,
    openedBlocks: 0,
    closedBlocks: 0,
  };
  const acpArtifactWriteToolCallIds = new Set<string>();
  // Per toolCallId: accumulate name/input/path/result across partial ACP frames
  // and emit exactly one tool_use + one tool_result at terminal status (or on
  // prompt flush for still-open tools). Think-only tools are tracked but never
  // transcribed and never flip emittedConcreteToolEvent. Entries stay after
  // emit so a repeated terminal frame cannot re-create + re-emit.
  type AcpToolNameSource = 'kind' | 'other';
  type AcpToolRunState = {
    name: string;
    nameSource: AcpToolNameSource;
    input: Record<string, unknown>;
    path: string | null;
    pathRank: number;
    resultContent: string;
    /** Sticky: once true, never cleared by later status-only frames. */
    thinkOnly: boolean;
    firstSeenAt: number;
    emitted: boolean;
  };
  const acpToolRunEventState = new Map<string, AcpToolRunState>();

  const buildToolUseInput = (st: AcpToolRunState): Record<string, unknown> => {
    const input = { ...st.input };
    if (st.path) input.file_path = st.path;
    else delete input.file_path;
    return input;
  };

  const emitTerminalToolPair = (toolCallId: string, st: AcpToolRunState, isError: boolean) => {
    if (st.emitted) return;
    st.emitted = true;
    // Think/reason frames are activity noise for AMR no-output detection and
    // must not appear as concrete tool_use/tool_result events.
    if (st.thinkOnly) return;
    // Raw ACP toolCallId stays as the local Map key for frame correlation; the
    // transcript/telemetry id is always an opaque hash so adapter-supplied
    // ids (paths, tokens, JWTs) never leak into Langfuse span ids or
    // metadata.toolCallId.
    const telemetryToolCallId = acpTelemetryToolCallId(toolCallId);
    send('agent', {
      type: 'tool_use',
      id: telemetryToolCallId,
      name: st.name,
      input: buildToolUseInput(st),
      // Wall-clock start of the first ACP frame for this toolCallId so analytics
      // can compute real duration even though tool_use is emitted at terminal.
      startedAt: st.firstSeenAt,
    });
    send('agent', {
      type: 'tool_result',
      toolUseId: telemetryToolCallId,
      // Bash/execute stdout can dump private files (cat .env). Langfuse only
      // lexically masks Bash, so redact before the canonical transcript ships.
      content: acpSafeToolResultContent(st.name, st.resultContent),
      isError,
    });
    // Concrete only on terminal tool_result for a real (non-think) tool.
    emittedConcreteToolEvent = true;
  };

  // Flush tools that never received a terminal `tool_call_update`. Clean
  // completion uses isError=false (best-effort close); fail paths use
  // isError=true so Langfuse/PostHog and the persisted transcript keep the
  // open tool as an errored result instead of dropping it entirely.
  //
  // Do not clear the map after flush. Emitted entries must stay until the
  // session ends so a late/racy terminal `tool_call_update` (timeout/abort/
  // prompt-response flush racing buffered stdout) cannot recreate the same
  // id as a fresh open tool and emit a second, possibly contradictory
  // tool_use/tool_result pair. `st.emitted` already suppresses re-emission.
  const flushOpenAcpTools = (isError = false) => {
    for (const [toolCallId, st] of acpToolRunEventState) {
      if (st.emitted) continue;
      emitTerminalToolPair(toolCallId, st, isError);
    }
  };

  const stageWatchdogDisabled = stageTimeoutMs <= 0;
  const resetStageTimer = (label: string) => {
    if (stageTimer) clearTimeout(stageTimer);
    // `stageTimeoutMs <= 0` disables the watchdog. Mirrors the outer chat
    // inactivity watchdog escape hatch (see server.ts → inactivityTimer).
    // Without this, an operator setting `OD_ACP_STAGE_TIMEOUT_MS=0` would
    // schedule a 0ms timeout that fires on the next tick and kills the
    // session immediately.
    if (stageWatchdogDisabled) return;
    stageTimer = setTimeout(() => {
      fail(`ACP ${label} timed out after ${stageTimeoutMs}ms`);
    }, stageTimeoutMs);
  };

  const clearStageTimer = () => {
    if (stageTimer) clearTimeout(stageTimer);
    stageTimer = null;
  };

  const amrModelUnavailablePayload = (message: string) => ({
    message,
    error: {
      code: 'AMR_MODEL_UNAVAILABLE',
      message,
      retryable: false,
      details: { kind: 'amr_model', action: 'choose_model' },
    },
  });

  const isModelUnavailableError = (message: string) => {
    const value = message.toLowerCase();
    return (
      value.includes('model not found') ||
      value.includes('providermodelnotfounderror') ||
      value.includes('unknown model') ||
      value.includes('invalid model')
    );
  };

  const failWithPayload = (payload: unknown) => {
    if (finished) return;
    // Emit pending tools as errored before terminal state so deferred
    // tool_use pairs are not lost on timeout / process death / RPC error.
    flushOpenAcpTools(true);
    finished = true;
    fatal = true;
    clearStageTimer();
    send('error', payload);
    if (!child.killed) child.kill('SIGTERM');
  };

  const fail = (
    message: string,
    options: { forceModelUnavailable?: boolean; details?: unknown; retryable?: boolean } = {},
  ) => {
    if (finished) return;
    // Emit pending tools as errored before terminal state so deferred
    // tool_use pairs are not lost on timeout / process death / RPC error.
    flushOpenAcpTools(true);
    finished = true;
    fatal = true;
    clearStageTimer();
    const useModelUnavailable =
      modelUnavailableErrorCode &&
      (options.forceModelUnavailable || isModelUnavailableError(message));
    send(
      'error',
      useModelUnavailable
        ? amrModelUnavailablePayload(message)
        : options.details === undefined && options.retryable === undefined
          ? { message }
          : {
              message,
              error: {
                code: 'AGENT_EXECUTION_FAILED',
                message,
                retryable: options.retryable ?? false,
                ...(options.details === undefined ? {} : { details: options.details }),
              },
            },
    );
    if (!child.killed) child.kill('SIGTERM');
  };

  const writeRpc = (id: JsonRpcId, method: string, params: unknown, timeoutLabel: string) => {
    resetStageTimer(timeoutLabel);
    try {
      sendRpc(stdin, id, method, params);
    } catch (err) {
      fail(`stdin write failed: ${errorMessage(err)}`);
    }
  };

  const emitAcpRawShapeDiagnostic = (update: JsonObject) => {
    if (!modelUnavailableErrorCode) return;
    if (rawAcpShapeDiagnosticCount >= ACP_RAW_EVENT_SHAPE_DIAGNOSTIC_LIMIT) return;
    rawAcpShapeDiagnosticCount += 1;
    send('agent', {
      type: 'diagnostic',
      name: 'acp_raw_event_shape',
      source: 'acp-json-rpc',
      elapsedMs: Date.now() - runStartedAt,
      shape: acpRawEventShape(update),
    });
  };

  const emitAcpExecutionObservability = (update: JsonObject): boolean => {
    const name = typeof update.sessionUpdate === 'string' ? update.sessionUpdate : '';
    if (
      name !== 'assistant_message_lifecycle' &&
      name !== 'model_step_lifecycle' &&
      name !== 'model_retry'
    ) {
      return false;
    }
    const numberField = (key: string) => {
      const value = update[key];
      return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
    };
    const stringField = (key: string) => {
      const value = update[key];
      return typeof value === 'string' && value.trim() ? value.trim() : undefined;
    };
    const usage = asObject(update.usage);
    send('agent', {
      type: 'diagnostic',
      name,
      source: 'amr-opencode',
      elapsedMs: Date.now() - runStartedAt,
      ...(stringField('phase') ? { phase: stringField('phase') } : {}),
      ...(stringField('status') ? { status: stringField('status') } : {}),
      ...(stringField('reason') ? { reason: stringField('reason') } : {}),
      ...(stringField('provider') ? { provider: stringField('provider') } : {}),
      ...(stringField('model') ? { model: stringField('model') } : {}),
      ...(stringField('errorClass') ? { errorClass: stringField('errorClass') } : {}),
      ...(stringField('timingEvidence')
        ? { timingEvidence: stringField('timingEvidence') }
        : {}),
      ...(numberField('assistantMessageIndex') !== undefined
        ? { assistantMessageIndex: numberField('assistantMessageIndex') }
        : {}),
      ...(numberField('stepIndex') !== undefined
        ? { stepIndex: numberField('stepIndex') }
        : {}),
      ...(numberField('startedAtMs') !== undefined
        ? { startedAtMs: numberField('startedAtMs') }
        : {}),
      ...(numberField('endedAtMs') !== undefined
        ? { endedAtMs: numberField('endedAtMs') }
        : {}),
      ...(numberField('durationMs') !== undefined
        ? { durationMs: numberField('durationMs') }
        : {}),
      ...(numberField('attempt') !== undefined
        ? { attempt: numberField('attempt') }
        : {}),
      ...(usage
        ? {
            usage: {
              ...(typeof usage.inputTokens === 'number'
                ? { inputTokens: usage.inputTokens }
                : {}),
              ...(typeof usage.outputTokens === 'number'
                ? { outputTokens: usage.outputTokens }
                : {}),
              ...(typeof usage.totalTokens === 'number'
                ? { totalTokens: usage.totalTokens }
                : {}),
              ...(typeof usage.reasoningTokens === 'number'
                ? { reasoningTokens: usage.reasoningTokens }
                : {}),
              ...(typeof usage.cacheReadTokens === 'number'
                ? { cacheReadTokens: usage.cacheReadTokens }
                : {}),
              ...(typeof usage.cacheWriteTokens === 'number'
                ? { cacheWriteTokens: usage.cacheWriteTokens }
                : {}),
            },
          }
        : {}),
    });
    return true;
  };

  const emitVisibleTextDelta = (delta: string) => {
    if (!delta) return;
    emittedVisibleTextChunk = true;
    if (!emittedFirstTokenStatus) {
      emittedFirstTokenStatus = true;
      send('agent', {
        type: 'status',
        label: 'streaming',
        ttftMs: Date.now() - runStartedAt,
      });
    }
    send('agent', { type: 'text_delta', delta });
  };

  const noteArtifactTextSuppression = (reason: string) => {
    if (!dsmlArtifactSuppressor) return;
    const stats = dsmlArtifactSuppressor.stats();
    const suppressedDelta = stats.suppressedChars - dsmlArtifactSuppressorLastSuppressedChars;
    if (suppressedDelta <= 0) return;
    dsmlArtifactSuppressorLastSuppressedChars = stats.suppressedChars;
    artifactTextSuppressionSummary.suppressedChars += suppressedDelta;
    artifactTextSuppressionSummary.suppressedChunks = stats.suppressedChunks;
    artifactTextSuppressionSummary.openedBlocks = stats.openedBlocks;
    artifactTextSuppressionSummary.closedBlocks = stats.closedBlocks;
    if (artifactSuppressionDiagnosticCount >= ACP_RAW_EVENT_SHAPE_DIAGNOSTIC_LIMIT) return;
    artifactSuppressionDiagnosticCount += 1;
    send('agent', {
      type: 'diagnostic',
      name: 'acp_artifact_text_suppression',
      source: 'acp-json-rpc',
      elapsedMs: Date.now() - runStartedAt,
      reason,
      suppressedChars: artifactTextSuppressionSummary.suppressedChars,
      suppressedChunks: artifactTextSuppressionSummary.suppressedChunks,
      openedBlocks: artifactTextSuppressionSummary.openedBlocks,
      closedBlocks: artifactTextSuppressionSummary.closedBlocks,
      pendingCandidateChars: stats.pendingCandidateChars,
      suppressing: stats.suppressing,
    });
  };

  const emitArtifactTextSuppressionSummary = () => {
    if (artifactTextSuppressionSummary.suppressedChars <= 0) return;
    if (executionProfile === 'filesystem') {
      send('agent', {
        type: 'diagnostic',
        name: 'unexpected_text_artifact_in_filesystem_run',
        source: 'acp-json-rpc',
        elapsedMs: Date.now() - runStartedAt,
        suppressedChars: artifactTextSuppressionSummary.suppressedChars,
        suppressedChunks: artifactTextSuppressionSummary.suppressedChunks,
        openedBlocks: artifactTextSuppressionSummary.openedBlocks,
        closedBlocks: artifactTextSuppressionSummary.closedBlocks,
      });
    }
    send('agent', {
      type: 'diagnostic',
      name: 'acp_artifact_text_suppression_summary',
      source: 'acp-json-rpc',
      elapsedMs: Date.now() - runStartedAt,
      ...artifactTextSuppressionSummary,
    });
  };

  const noteToolCallTextSuppression = (reason: string) => {
    const stats = toolCallTextSuppressor.stats();
    const suppressedDelta = stats.suppressedChars - toolCallTextSuppressorLastSuppressedChars;
    if (suppressedDelta <= 0) return;
    toolCallTextSuppressorLastSuppressedChars = stats.suppressedChars;
    toolCallTextSuppressionSummary.suppressedChars += suppressedDelta;
    toolCallTextSuppressionSummary.suppressedChunks = stats.suppressedChunks;
    toolCallTextSuppressionSummary.openedBlocks = stats.openedBlocks;
    toolCallTextSuppressionSummary.closedBlocks = stats.closedBlocks;
    if (artifactSuppressionDiagnosticCount >= ACP_RAW_EVENT_SHAPE_DIAGNOSTIC_LIMIT) return;
    artifactSuppressionDiagnosticCount += 1;
    send('agent', {
      type: 'diagnostic',
      name: 'acp_tool_call_text_suppression',
      source: 'acp-json-rpc',
      elapsedMs: Date.now() - runStartedAt,
      reason,
      suppressedChars: toolCallTextSuppressionSummary.suppressedChars,
      suppressedChunks: toolCallTextSuppressionSummary.suppressedChunks,
      openedBlocks: toolCallTextSuppressionSummary.openedBlocks,
      closedBlocks: toolCallTextSuppressionSummary.closedBlocks,
      pendingCandidateChars: stats.pendingCandidateChars,
      suppressing: stats.suppressing,
    });
  };

  const emitToolCallTextSuppressionSummary = () => {
    if (toolCallTextSuppressionSummary.suppressedChars <= 0) return;
    send('agent', {
      type: 'diagnostic',
      name: 'acp_tool_call_text_suppression_summary',
      source: 'acp-json-rpc',
      elapsedMs: Date.now() - runStartedAt,
      ...toolCallTextSuppressionSummary,
    });
  };

  const sendPrompt = () => {
    promptRequestId = nextId;
    expectedId = promptRequestId;
    writeRpc(
      promptRequestId,
      'session/prompt',
      {
        sessionId,
        prompt: buildPromptBlocks(prompt, imagePaths),
      },
      'session/prompt',
    );
    send('agent', {
      type: 'status',
      label: 'waiting_for_first_output',
      elapsedMs: Date.now() - runStartedAt,
    });
    nextId += 1;
  };

  // Best-effort: emit provider usage before terminal fail/success so failed
  // ACP runs still contribute token fields to PostHog/Langfuse when the agent
  // returned a usage object on the prompt result.
  const emitUsageIfPresent = (usageSource?: unknown) => {
    const usage = formatUsage(usageSource);
    if (!usage) return;
    send('agent', {
      type: 'usage',
      usage,
      durationMs: Date.now() - runStartedAt,
    });
  };

  const finishCleanPrompt = (usageSource?: unknown) => {
    if (finished) return;
    // Mark the prompt finished before notifying observers so duplicate results
    // and callback re-entry cannot report clean completion more than once.
    finished = true;
    onPromptComplete?.();
    // Flush any tools still open when the prompt completes so traces stay
    // complete (one tool_use + tool_result per id).
    flushOpenAcpTools();
    const flushedToolText = toolCallTextSuppressor.flush();
    noteToolCallTextSuppression('tool_call_xml_flush');
    const flushedText = flushedToolText ? (dsmlArtifactSuppressor?.strip(flushedToolText) ?? flushedToolText) : '';
    if (flushedText) {
      emitVisibleTextDelta(flushedText);
    }
    noteArtifactTextSuppression('artifact_flush');
    emitToolCallTextSuppressionSummary();
    emitArtifactTextSuppressionSummary();
    emitUsageIfPresent(usageSource);
    clearStageTimer();
    stdin.end();
    // Some ACP agents keep the child process alive after stdin closes,
    // waiting for another prompt. Each OpenDesign run owns one process per
    // turn, so close it once this prompt is cleanly complete.
    const cleanExitTimer = setTimeout(() => {
      if (!child.killed) child.kill('SIGTERM');
    }, 500);
    child.once('close', () => clearTimeout(cleanExitTimer));
  };

  const replyPermission = (raw: JsonObject) => {
    const params = asObject(raw.params);
    const optionId = choosePermissionOutcome(params?.options);
    if (!optionId || !isJsonRpcId(raw.id)) {
      fail(`unhandled ACP permission request: ${JSON.stringify(raw)}`);
      return;
    }
    // E-lite: the ACP path is the only daemon-observable approval gate. Surface
    // it so `run_finished.approval_requested` can attribute a `tool_execution`
    // stall to an approval hang even though we auto-approve here.
    send('agent', {
      type: 'diagnostic',
      name: 'acp_approval_request',
      source: 'acp-json-rpc',
      elapsedMs: Date.now() - runStartedAt,
      optionId,
    });
    resetStageTimer('session/request_permission');
    try {
      sendRpcResult(stdin, raw.id, {
        outcome: { outcome: 'selected', optionId },
      });
    } catch (err) {
      fail(`stdin write failed: ${errorMessage(err)}`);
    }
  };

  const recoverFromModelSelectionError = () => {
    setModelRequestId = null;
    activeModel = activeModel || 'default';
    send('agent', { type: 'status', label: 'model', model: activeModel });
    sendPrompt();
  };

  const parser = createJsonLineStream((raw, rawLine) => {
    if (aborted || finished) return;
    resetStageTimer('response');
    const obj = asObject(raw);
    if (!obj) return;
    // First well-formed ACP JSON-RPC message = CLI ready (#3408 §4). Caller
    // dedupes, so re-notifying on later messages is harmless.
    onCliReady?.();
    const error = asObject(obj.error);
    const params = asObject(obj.params);
    const result = asObject(obj.result);
    const rpcErr = rpcErrorMessage(obj);
    if (rpcErr) {
      // After response completion, any late-arriving errors from the agent
      // (pipe-broken, cleanup race conditions, etc.) are safe to ignore.
      if (finished) return;
      // JSON-RPC error handling:
      // -32603 unexpected-id errors are cleanup noise. Expected-id model
      // selection failures are recoverable; all other RPC errors are real
      // protocol failures for initialize/session/new/session/prompt.
      if (
        obj.id === setModelRequestId &&
        modelSelectionErrorIsRecoverable(error?.code) &&
        promptRequestId === null
      ) {
        recoverFromModelSelectionError();
        return;
      }
      if (error?.code === -32603 && obj.id !== expectedId) {
        return;
      }
      const details = rpcErrorData(obj);
      const promotedPayload = promotedOpenCodeSessionErrorPayload(details, rpcErr);
      if (promotedPayload) {
        failWithPayload(promotedPayload);
        return;
      }
      const retryable = rpcErrorRetryable(details) ?? inferRpcErrorRetryable(rpcErr, details);
      fail(rpcErr, {
        details,
        ...(retryable === undefined ? {} : { retryable }),
      });
      return;
    }
    if (obj.method === 'session/request_permission') {
      replyPermission(obj);
      return;
    }
    const update = asObject(params?.update);
    if (obj.method === 'session/update' && update) {
      if (modelUnavailableErrorCode) {
        const promotedPayload = promotedAmrRetryStatusPayload(update);
        if (promotedPayload) {
          failWithPayload(promotedPayload);
          return;
        }
      }
      if (emitAcpExecutionObservability(update)) {
        return;
      }
      if (update.sessionUpdate !== 'agent_message_chunk' && update.sessionUpdate !== 'agent_thought_chunk') {
        const detail = extractAcpStatusDetail(update);
        send('agent', {
          type: 'status',
          label: String(update.sessionUpdate || 'session_update'),
          ...(detail ? { detail } : {}),
          elapsedMs: Date.now() - runStartedAt,
        });
        emitAcpRawShapeDiagnostic(update);
      }
      if (
        completePromptOnTurnEnd &&
        promptRequestId !== null &&
        update.sessionUpdate === 'turn_end'
      ) {
        finishCleanPrompt(update.usage);
        return;
      }
      if (update.sessionUpdate === 'agent_thought_chunk') {
        emitAcpRawShapeDiagnostic(update);
        const text = extractAcpUpdateText(update);
        if (text) {
          if (!emittedThinkingStart) {
            emittedThinkingStart = true;
            send('agent', { type: 'thinking_start' });
          }
          send('agent', { type: 'thinking_delta', delta: text });
        }
        return;
      }
      if (update.sessionUpdate === 'agent_message_chunk') {
        emitAcpRawShapeDiagnostic(update);
        const text = extractAcpUpdateText(update);
        if (text) {
          const isCumulativeSnapshot = text.startsWith(emittedTextBuffer);
          const delta = isCumulativeSnapshot
            ? text.slice(emittedTextBuffer.length)
            : text;
          if (delta.length > 0) {
            emittedTextChunk = true;
            emittedTextBuffer += delta;
            const wasSuppressingToolCall = toolCallTextSuppressor.isSuppressing();
            const toolCallStrippedDelta = toolCallTextSuppressor.strip(delta);
            noteToolCallTextSuppression(
              wasSuppressingToolCall || toolCallStrippedDelta !== delta
                ? 'tool_call_xml'
                : 'tool_call_candidate',
            );
            if (!toolCallStrippedDelta) {
              return;
            }
            if (dsmlArtifactSuppressor) {
              const wasSuppressingArtifact = dsmlArtifactSuppressor.isSuppressing();
              const hadPendingArtifactCandidate = dsmlArtifactSuppressor.hasPendingCandidate();
              const strippedDelta = dsmlArtifactSuppressor.strip(toolCallStrippedDelta);
              noteArtifactTextSuppression(
                wasSuppressingArtifact || strippedDelta !== toolCallStrippedDelta
                  ? 'artifact_echo'
                  : 'artifact_candidate',
              );
              const hasOpenArtifactCandidate =
                dsmlArtifactSuppressor.isSuppressing() || dsmlArtifactSuppressor.hasPendingCandidate();
              const consumedArtifactText = wasSuppressingArtifact || strippedDelta !== delta;
              const shouldPreserveIncrementalProse =
                !isCumulativeSnapshot &&
                !wasSuppressingArtifact &&
                !hadPendingArtifactCandidate &&
                !hasOpenArtifactCandidate &&
                (
                  strippedDelta === toolCallStrippedDelta ||
                  (
                    !dsmlArtifactSuppressorArmedAfterText &&
                    dsmlArtifactSuppressorSawIncrementalProse &&
                    !ACP_ARTIFACT_ECHO_START_RE.test(toolCallStrippedDelta)
                  )
                );
              const outputDelta = shouldPreserveIncrementalProse ? toolCallStrippedDelta : strippedDelta;
              if (outputDelta) {
                emitVisibleTextDelta(outputDelta);
              }
              if (
                strippedDelta === toolCallStrippedDelta &&
                !wasSuppressingArtifact &&
                !hadPendingArtifactCandidate &&
                !hasOpenArtifactCandidate
              ) {
                dsmlArtifactSuppressorSawIncrementalProse = true;
              }
              if (consumedArtifactText && !hasOpenArtifactCandidate) {
                dsmlArtifactSuppressor = null;
                dsmlArtifactSuppressorToolCallId = null;
                dsmlArtifactSuppressorArmedAfterText = false;
                dsmlArtifactSuppressorSawIncrementalProse = false;
              }
            } else {
              emitVisibleTextDelta(toolCallStrippedDelta);
            }
          }
        }
        return;
      }
      if (
        update.sessionUpdate === 'tool_call' ||
        update.sessionUpdate === 'tool_call_update'
      ) {
        // The turn did real work (a tool call / file edit), which is valid output even
        // when the model emits no closing assistant text. Track it so the prompt-complete
        // handler does not misreport such a turn as "no output / model unavailable".
        emittedToolCall = true;
        const toolCallId = acpToolCallId(update);
        if (toolCallId && isAcpArtifactWriteLabel(update)) {
          acpArtifactWriteToolCallIds.add(toolCallId);
        }
        // Full ACP tool transcript → canonical tool_use/tool_result events for
        // Langfuse/PostHog and `countNewArtifacts` (run-artifacts.ts). Every
        // non-think tool is mirrored once at terminal status (accumulate
        // partial frames first). Write tools keep Claude-shaped Write/Edit
        // names and a real `file_path` when present. Never use toolCallId as
        // file_path.
        if (toolCallId) {
          const nextName = acpToolName(update);
          const nextInput = acpToolInput(update);
          const nextPath = acpArtifactWritePathRanked(update);
          const nextResult = acpToolResultContent(update);
          const nextThinkOnly = isAcpThinkOnlyTool(update);
          const kindRaw = typeof update.kind === 'string' ? update.kind.trim() : '';
          const nameFromKind = Boolean(kindRaw && isAcpRecognizedKind(kindRaw));
          let st = acpToolRunEventState.get(toolCallId);
          if (!st) {
            st = {
              name: nextName,
              nameSource: nameFromKind ? 'kind' : 'other',
              input: nextInput,
              path: nextPath?.path ?? null,
              pathRank: nextPath?.rank ?? 0,
              resultContent: nextResult,
              thinkOnly: nextThinkOnly,
              firstSeenAt: Date.now(),
              emitted: false,
            };
            acpToolRunEventState.set(toolCallId, st);
          } else if (!st.emitted) {
            // Kind-locked names must not be overwritten by later title-only frames
            // (e.g. kind:read then title "Update cache" must stay Read).
            if (nameFromKind) {
              st.name = nextName;
              st.nameSource = 'kind';
            } else if (st.nameSource !== 'kind') {
              // Prefer a more specific name over the generic fallback.
              if (nextName !== 'Tool' || st.name === 'Tool') st.name = nextName;
            }
            // Shallow merge rawInput; later keys win.
            st.input = { ...st.input, ...nextInput };
            // Upgrade path when a higher-precedence source appears.
            if (nextPath && (!st.path || nextPath.rank >= st.pathRank)) {
              st.path = nextPath.path;
              st.pathRank = nextPath.rank;
            }
            // Keep last non-empty result payload (terminal may be status-only).
            if (nextResult) st.resultContent = nextResult;
            // Sticky think-only: once classified, never clear on later frames
            // (terminal status-only frames have no title and would otherwise
            // flip thinkOnly false and emit a fake concrete tool).
            if (nextThinkOnly) st.thinkOnly = true;
          }
          if (isAcpTerminalToolStatus(update)) {
            const failed = isAcpTerminalFailureStatus(update);
            emitTerminalToolPair(toolCallId, st, failed);
            // Keep the entry (emitted=true) so a repeated terminal cannot re-emit.
          }
        }
        if (isAcpArtifactWriteUpdate(update, acpArtifactWriteToolCallIds)) {
          dsmlArtifactSuppressor = createDsmlArtifactTextSuppressor();
          dsmlArtifactSuppressorLastSuppressedChars = 0;
          dsmlArtifactSuppressorToolCallId = toolCallId;
          dsmlArtifactSuppressorArmedAfterText = emittedTextBuffer.length > 0;
          dsmlArtifactSuppressorSawIncrementalProse = false;
          if (toolCallId) acpArtifactWriteToolCallIds.delete(toolCallId);
        } else if (toolCallId && isAcpTerminalFailureStatus(update)) {
          const ownsPendingWriteSuppression = toolCallId === dsmlArtifactSuppressorToolCallId;
          const ownsPendingWriteCall = acpArtifactWriteToolCallIds.has(toolCallId);
          acpArtifactWriteToolCallIds.delete(toolCallId);
          if (ownsPendingWriteSuppression || ownsPendingWriteCall) {
            dsmlArtifactSuppressor = null;
            dsmlArtifactSuppressorToolCallId = null;
            dsmlArtifactSuppressorArmedAfterText = false;
            dsmlArtifactSuppressorSawIncrementalProse = false;
          }
        }
        return;
      }
      return;
    }
    if (obj.id !== expectedId || !result) {
      return;
    }
    if (expectedId === 1) {
      expectedId = nextId;
      if (resumeSessionId) {
        // Resume the prior upstream session instead of creating a fresh one.
        writeRpc(
          nextId,
          'session/load',
          { sessionId: resumeSessionId, cwd: effectiveCwd },
          'session/load',
        );
      } else {
        writeRpc(
          nextId,
          'session/new',
          buildAcpSessionNewParams(
            effectiveCwd,
            mcpServers ? { mcpServers, envFormat } : { envFormat },
          ),
          'session/new',
        );
      }
      nextId += 1;
      return;
    }
    if (expectedId === 2) {
      sessionId = typeof result.sessionId === 'string' ? result.sessionId : null;
      // The durable handle for resuming this session on the next turn.
      durableSessionId =
        typeof result.openCodeSessionId === 'string' ? result.openCodeSessionId : null;
      // session/new acknowledged with a session id = handshake done (#3408 §4).
      if (sessionId) onSessionInit?.();
      const modelConfig = findModelConfigOption(result.configOptions);
      modelConfigId = modelConfig?.configId ?? null;
      activeModel = currentModelFromSessionResult(result);
      if (sessionId && activeModel) {
        send('agent', { type: 'status', label: 'model', model: activeModel });
      }
      if (sessionId && model && model !== 'default') {
        setModelRequestId = nextId;
        expectedId = nextId;
        const setModelMethod = modelConfigId ? 'session/set_config_option' : 'session/set_model';
        const setModelParams = modelConfigId
          ? { sessionId, configId: modelConfigId, value: model }
          : { sessionId, modelId: model };
        writeRpc(
          nextId,
          setModelMethod,
          setModelParams,
          setModelMethod,
        );
        nextId += 1;
        return;
      }
      if (!sessionId) {
        fail(`invalid session/new response: ${rawLine}`);
        return;
      }
      sendPrompt();
      return;
    }
    if (promptRequestId !== null && obj.id === promptRequestId) {
      // Flush still-open tools before AMR no-output classification. A successful
      // session/prompt may omit a terminal tool_call_update; clean-closing those
      // pending non-think tools flips emittedConcreteToolEvent so we take
      // finishCleanPrompt instead of acp_no_visible_output (which would re-flush
      // them as isError via fail()). Think-only open tools do not flip the flag.
      flushOpenAcpTools();
      const usage = formatUsage(result.usage);
      if (!emittedVisibleTextChunk && !emittedConcreteToolEvent && modelUnavailableErrorCode) {
        const outputTokens = usage?.output_tokens;
        const hadCompletionTokens = typeof outputTokens === 'number' && outputTokens > 0;
        // Emit usage before fail so analytics still sees provider tokens.
        emitUsageIfPresent(result.usage);
        if (hadCompletionTokens || emittedToolCall || emittedTextChunk) {
          fail(
            'ACP session completed after reporting model activity, but did not produce visible assistant text, concrete tool results, or artifacts.',
            {
              retryable: true,
              details: {
                kind: 'acp_no_visible_output',
                output_tokens: outputTokens,
                raw_tool_update_seen: emittedToolCall,
                text_chunk_seen: emittedTextChunk,
              },
            },
          );
        } else {
          fail(
            'ACP session completed without producing any assistant text. Refresh the AMR model list, choose a supported model, and retry this run.',
            { forceModelUnavailable: true },
          );
        }
        return;
      }
      finishCleanPrompt(result.usage);
      return;
    }
    if (sessionId && model && model !== 'default' && obj.id === expectedId) {
      activeModel = currentModelFromSessionResult(result) ?? model;
      send('agent', { type: 'status', label: 'model', model: activeModel });
      sendPrompt();
    }
  });

  stdout.on('data', (chunk: string) => parser.feed(chunk));
  child.stderr?.setEncoding('utf8');
  child.stderr?.on('data', (chunk: string) => {
    if (!modelUnavailableErrorCode || finished) return;
    amrStderrRetryTail = `${amrStderrRetryTail}${String(chunk)}`.slice(
      -AMR_STDERR_RETRY_TAIL_LIMIT,
    );
    const promotedPayload = promotedAmrStderrPayload(amrStderrRetryTail);
    if (promotedPayload) failWithPayload(promotedPayload);
  });
  child.on('close', (code, signal) => {
    clearStageTimer();
    parser.flush();
    if (!finished && !aborted && !fatal) {
      fail(`ACP session exited before completion (code=${code ?? 'null'}, signal=${signal ?? 'none'})`);
    }
  });
  child.on('error', (err: Error) => fail(err.message));
  stdin.on('error', (err: Error) => fail(`stdin error: ${err.message}`));

  writeRpc(1, 'initialize', {
    protocolVersion: ACP_PROTOCOL_VERSION,
    clientCapabilities: { terminal: false },
    clientInfo: { name: clientName, version: clientVersion },
  }, 'initialize');

  return {
    /** Returns `true` when the session ended with a fatal protocol or transport error, allowing the caller to surface the failure. */
    hasFatalError() {
      return fatal;
    },
    // The durable upstream session handle to persist for resume, or null when
    // none was reported (older agents, or a handshake that never established a
    // session). Mirrors pi-rpc's getLastSessionPath().
    /** Returns the durable upstream session id (e.g. vela's `openCodeSessionId`) to persist for next-turn resume, or `null` when the agent did not report one. */
    getDurableSessionId() {
      return durableSessionId;
    },
    /** Returns `true` when the prompt request resolved cleanly without a fatal error and without an abort, even if the child process later exited via SIGTERM. */
    completedSuccessfully() {
      // Returns true when the prompt request resolved without a fatal error
      // and was not aborted. The chat consumer treats this as a successful
      // run even if the child process subsequently exited via SIGTERM
      // (which is expected for agents that don't shut down on stdin.end()).
      return finished && !fatal && !aborted;
    },
    /**
     * Aborts an in-progress ACP session. Sends `session/cancel` when a session
     * id has already been established, then always closes stdin so the agent
     * receives EOF and can tear down its own runtime (e.g. vela's private
     * OpenCode server). Idempotent — subsequent calls are no-ops.
     */
    abort() {
      if (aborted || finished) return;
      // Flush deferred tool pairs as errored before terminal cancel. Tools are
      // held until a terminal tool_call_update; without this flush, user cancel
      // (runs.ts → acpSession.abort) drops in-progress tools from the transcript
      // and from Langfuse/PostHog — unlike timeout and child-exit fail paths.
      flushOpenAcpTools(true);
      aborted = true;
      finished = true;
      clearStageTimer();
      if (!child.stdin || child.stdin.destroyed || child.stdin.writableEnded)
        return;
      // Only cancel an established session; before session/new resolves there
      // is no sessionId to cancel, but we must still close stdin below.
      if (sessionId) {
        try {
          sendRpc(child.stdin, nextId, 'session/cancel', { sessionId });
          nextId += 1;
        } catch {
          // The caller owns process-signal fallback if the ACP transport is gone.
        }
      }
      // Always close stdin so the agent receives EOF and shuts down its own
      // runtime — the vela ACP bridge tears down its private OpenCode server on
      // EOF — instead of lingering (and leaking that server) until the caller's
      // SIGTERM fallback fires. This also covers aborts during ACP startup,
      // before session/new returns. Mirrors the clean-completion path above.
      try {
        child.stdin.end();
      } catch {
        // Best effort; the caller still owns the SIGTERM/SIGKILL fallback.
      }
    },
  };
}

/** @module agent-protocol/acp/types
 * Shared primitive type aliases for the ACP JSON-RPC transport layer.
 * Consumed by every other file in acp/; depends only on Node built-ins and
 * carries no runtime code.
 */
import type { Writable } from 'node:stream';
import type { ChildProcess } from 'node:child_process';

/** A JSON-RPC 2.0 request or response identifier. May be a numeric integer or a string. */
export type JsonRpcId = string | number;
/** An arbitrary JSON object with string keys and unknown values. Used as a loose type for parsed RPC frames. */
export type JsonObject = Record<string, unknown>;
/** Minimal writable interface required to send JSON-RPC newline-delimited frames to an ACP agent's stdin. */
export type RpcWritable = Pick<Writable, 'write' | 'end'>;
/** The Node `ChildProcess` handle for a spawned ACP agent subprocess. */
export type AcpChildProcess = ChildProcess;
/** Opaque handle returned by `setTimeout`, used for stage watchdog timers in acp/session.ts and acp/models.ts. */
export type TimerHandle = ReturnType<typeof setTimeout>;

/** @module agent-protocol/acp/updates
 * ACP session-update classification helpers: status normalisation,
 * artifact-write detection, AMR retry/stderr failure promotion, and raw
 * event-shape diagnostics. Depends on acp/types, acp/json, and the vela-errors
 * integration; consumed exclusively by acp/session.ts.
 */
import { createHash } from 'node:crypto';
import type { JsonObject } from './types.js';
import { asObject, acpValueKind, objectKeys, extractAcpUpdateText } from './json.js';
import { classifyAmrAccountFailure, amrAccountFailureDetails } from '../../integrations/vela-errors.js';

/**
 * Produces a shallow diagnostic snapshot of an ACP update object for the
 * `acp_raw_event_shape` diagnostic event. Captures key presence, value kinds,
 * and content structure without serialising the full update, so the payload
 * stays bounded in size. Emitted only for AMR sessions where unknown shapes
 * may require debugging.
 *
 * @param update - A parsed ACP `session/update` params object.
 * @returns A flat diagnostic object suitable for inclusion in an agent event payload.
 */
export function acpRawEventShape(update: JsonObject) {
  const content = update.content;
  const rawInput = update.rawInput;
  const locations = update.locations;
  return {
    sessionUpdate: typeof update.sessionUpdate === 'string' ? update.sessionUpdate : null,
    keys: objectKeys(update),
    contentKind: acpValueKind(content),
    contentKeys: objectKeys(content),
    hasText: Boolean(extractAcpUpdateText(update)),
    hasTopLevelText: typeof update.text === 'string' && update.text.length > 0,
    hasTopLevelDelta: typeof update.delta === 'string' && update.delta.length > 0,
    hasTopLevelMessage: update.message !== undefined,
    hasToolCallId: acpToolCallId(update) !== null,
    hasRawInput: rawInput !== undefined,
    rawInputKind: acpValueKind(rawInput),
    rawInputKeys: objectKeys(rawInput),
    locationsKind: acpValueKind(locations),
    locationsCount: Array.isArray(locations) ? locations.length : undefined,
    status: typeof update.status === 'string' ? update.status : undefined,
    titlePresent: typeof update.title === 'string' && update.title.length > 0,
  };
}
/**
 * Normalises the `status` field of an ACP update to a lowercase,
 * whitespace-and-punctuation-stripped token. Returns `''` when the field
 * is absent or not a string, so all status comparisons use the token form.
 *
 * @param update - A parsed ACP `session/update` params object.
 */
export function acpUpdateStatus(update: JsonObject): string {
  return typeof update.status === 'string'
    ? update.status.trim().toLowerCase().replace(/[\s_-]+/g, '')
    : '';
}
/**
 * Returns `true` when the update's `status` field represents a successful
 * terminal state (`completed`, `complete`, `succeeded`, or `success`).
 * Used to decide when to emit deferred artifact-write tool events.
 */
export function isAcpCompletedStatus(update: JsonObject): boolean {
  const status = acpUpdateStatus(update);
  return status === 'completed' || status === 'complete' || status === 'succeeded' || status === 'success';
}
/**
 * Returns `true` when the update's `status` field represents a terminal
 * failure state (`failed`, `failure`, `error`, `cancelled`, or `canceled`).
 * Used to clean up pending write-suppression state and emit failed tool events.
 */
export function isAcpTerminalFailureStatus(update: JsonObject): boolean {
  const status = acpUpdateStatus(update);
  return status === 'failed' || status === 'failure' || status === 'error' || status === 'cancelled' || status === 'canceled';
}
/**
 * Returns `true` when the update's status is a terminal tool outcome
 * (completed or failed). Used to decide when to emit `tool_result`.
 */
export function isAcpTerminalToolStatus(update: JsonObject): boolean {
  return isAcpCompletedStatus(update) || isAcpTerminalFailureStatus(update);
}
/**
 * Returns `true` when the update's status is `'retry'`. Signals that the AMR
 * agent wants to restart the request; the session promoter maps this to a
 * structured error payload via `promotedAmrRetryStatusPayload`.
 */
export function isAcpRetryStatus(update: JsonObject): boolean {
  return acpUpdateStatus(update) === 'retry';
}
/**
 * Recursively collects all text-bearing leaf values from an ACP update
 * (strings, numbers, booleans) up to 4 levels deep. Used to produce a flat
 * text corpus for `classifyAmrAccountFailure` pattern matching without
 * requiring knowledge of a specific agent's response shape.
 *
 * @param value - Any value from a parsed ACP session update.
 * @param depth - Current recursion depth (max 4); callers omit this.
 * @returns A flat array of trimmed non-empty string representations.
 */
export function acpUpdateDiagnosticText(value: unknown, depth = 0): string[] {
  if (depth > 4) return [];
  if (typeof value === 'string') return value.trim() ? [value] : [];
  if (typeof value === 'number' || typeof value === 'boolean') return [String(value)];
  if (Array.isArray(value)) {
    return value.flatMap((item) => acpUpdateDiagnosticText(item, depth + 1));
  }
  const obj = asObject(value);
  if (!obj) return [];
  const parts: string[] = [];
  for (const key of [
    'type',
    'status',
    'code',
    'message',
    'detail',
    'details',
    'error',
    'recovery',
    'pauseReason',
    'content',
    'text',
    'rawInput',
  ]) {
    if (key in obj) {
      parts.push(...acpUpdateDiagnosticText(obj[key], depth + 1));
    }
  }
  return parts;
}
/**
 * Promotes an AMR `retry` status update into a structured OpenDesign error
 * payload when the update's diagnostic text matches a known AMR account failure
 * pattern (e.g. quota exceeded, auth failure). Returns `null` when the update
 * is not a retry or does not match a known pattern.
 *
 * @param update - A parsed ACP `session/update` params object.
 * @returns A structured error payload with `message` and `error`, or `null`.
 */
export function promotedAmrRetryStatusPayload(update: JsonObject) {
  if (!isAcpRetryStatus(update)) return null;
  const diagnosticText = acpUpdateDiagnosticText(update).join('\n');
  const failure = classifyAmrAccountFailure(diagnosticText);
  if (!failure) return null;
  return {
    message: failure.message,
    error: {
      code: failure.code,
      message: failure.message,
      retryable: false,
      details: {
        ...amrAccountFailureDetails(failure),
        promoted_by: 'open_design_acp_retry_status',
      },
    },
  };
}
/**
 * Scans a rolling tail of AMR stderr output for known retry/session-failure
 * signals and promotes a match to a structured OpenDesign error payload.
 * Returns `null` when the chunk does not contain the expected markers or does
 * not match a known failure pattern.
 *
 * @param chunk - A tail slice of accumulated stderr bytes from the AMR subprocess.
 * @returns A structured error payload, or `null` when not applicable.
 */
export function promotedAmrStderrPayload(chunk: string) {
  if (!/opencode_event_stream_failure|session\.status/i.test(chunk)) return null;
  if (!/\bretry\b/i.test(chunk)) return null;
  const failure = classifyAmrAccountFailure(chunk);
  if (!failure) return null;
  return {
    message: failure.message,
    error: {
      code: failure.code,
      message: failure.message,
      retryable: false,
      details: {
        ...amrAccountFailureDetails(failure),
        promoted_by: 'open_design_acp_stderr_retry_status',
      },
    },
  };
}
/**
 * Extracts and trims the `toolCallId` string from an ACP update, or returns
 * `null` when absent or empty. Used as a stable dedup key for artifact-write
 * tracking across update frames.
 *
 * @param update - A parsed ACP `session/update` params object.
 */
export function acpToolCallId(update: JsonObject): string | null {
  return typeof update.toolCallId === 'string' && update.toolCallId.trim()
    ? update.toolCallId.trim()
    : null;
}
/** True when ACP `kind` is a recognized write/edit family token. */
function isAcpWriteEditKind(kind: string): boolean {
  const token = kind.trim().toLowerCase();
  return (
    token === 'edit' ||
    token === 'write' ||
    token === 'create' ||
    token === 'patch' ||
    token === 'replace' ||
    token === 'update' ||
    token === 'save'
  );
}

/**
 * True when ACP `kind` is a known tool family we trust over title heuristics.
 * Unknown kinds still map to a display name but do not lock the tool name
 * across partial frames (agents sometimes invent kind strings).
 */
export function isAcpRecognizedKind(kind: string): boolean {
  const token = kind.trim().toLowerCase();
  if (!token) return false;
  if (isAcpWriteEditKind(token)) return true;
  return (
    token === 'read' ||
    token === 'execute' ||
    token === 'bash' ||
    token === 'shell' ||
    token === 'terminal' ||
    token === 'search' ||
    token === 'grep' ||
    token === 'glob' ||
    token === 'think' ||
    token === 'thought' ||
    token === 'reason' ||
    token === 'reasoning' ||
    token === 'fetch' ||
    token === 'web' ||
    token === 'other'
  );
}

/**
 * Returns `true` when the update's `kind`, `title`, or `name` field indicates
 * a file-write operation (`edit`, `write`, `create`, `update`, `save`,
 * `patch`, or `replace`). Used to identify artifact-write tool calls for the
 * DSML suppressor (including kind-only write frames with no title words).
 *
 * @param update - A parsed ACP `session/update` params object.
 */
export function isAcpArtifactWriteLabel(update: JsonObject): boolean {
  if (typeof update.kind === 'string' && isAcpWriteEditKind(update.kind)) {
    return true;
  }
  const label = [
    typeof update.title === 'string' ? update.title : '',
    typeof update.name === 'string' ? update.name : '',
  ].join(' ');
  return /\b(?:edit|write|create|update|save|patch|replace)\b/i.test(label);
}

/**
 * Returns `true` when the tool is pure think/reason activity and must not
 * count as a concrete tool event for AMR no-output detection (and is omitted
 * from the tool_use/tool_result transcript).
 */
export function isAcpThinkOnlyTool(update: JsonObject): boolean {
  const kind = typeof update.kind === 'string' ? update.kind.trim().toLowerCase() : '';
  if (
    kind === 'think' ||
    kind === 'thought' ||
    kind === 'reason' ||
    kind === 'reasoning'
  ) {
    return true;
  }
  const name = typeof update.name === 'string' ? update.name.trim() : '';
  if (name && /^(think|thinking|thought|reason|reasoning)$/i.test(name)) {
    return true;
  }
  const title = typeof update.title === 'string' ? update.title.trim() : '';
  if (title && /^(think|thinking|thought|reason|reasoning)\b/i.test(title)) {
    return true;
  }
  return false;
}

/** Path source rank: higher wins when merging partial ACP frames. */
export const ACP_PATH_RANK_LOCATIONS = 3;
export const ACP_PATH_RANK_RAW_INPUT = 2;
export const ACP_PATH_RANK_TITLE = 1;

export type AcpPathCandidate = { path: string; rank: number };

/**
 * Best-effort path extraction with a precedence rank so partial-frame merges
 * can upgrade a weak title path when locations/rawInput arrive later.
 */
export function acpArtifactWritePathRanked(update: JsonObject): AcpPathCandidate | null {
  // 1. ACP `locations: [{ path }]` and `content: [{ path }]` (diff entries).
  for (const field of [update.locations, update.content]) {
    if (!Array.isArray(field)) continue;
    for (const entry of field) {
      const path = asObject(entry)?.path;
      if (typeof path === 'string' && path.trim()) {
        return { path: path.trim(), rank: ACP_PATH_RANK_LOCATIONS };
      }
    }
  }
  // 2. Tool input: path / file_path / filename / filePath (camelCase).
  const rawInput = asObject(update.rawInput);
  for (const key of ['path', 'file_path', 'filename', 'filePath']) {
    const value = rawInput?.[key];
    if (typeof value === 'string' && value.trim()) {
      return { path: value.trim(), rank: ACP_PATH_RANK_RAW_INPUT };
    }
  }
  // 3. A path-like filename token in the human title (reject `Image.open`).
  const title = typeof update.title === 'string' ? update.title : '';
  const match = title.match(/[\w./\\-]+\.[A-Za-z0-9]+/);
  if (match?.[0] && isAcpPathLikeToken(match[0])) {
    return { path: match[0], rank: ACP_PATH_RANK_TITLE };
  }
  return null;
}
/**
 * Returns `true` when an ACP update represents the terminal completion of an
 * artifact-write tool call and should arm the DSML text suppressor. Requires
 * a completed status combined with either a write-style label or a tool call
 * id tracked in `writeToolCallIds`.
 *
 * @param update - A parsed ACP `session/update` params object.
 * @param writeToolCallIds - The set of tool call ids identified as artifact writes so far.
 */
export function isAcpArtifactWriteUpdate(update: JsonObject, writeToolCallIds: Set<string>): boolean {
  if (!isAcpCompletedStatus(update)) return false;
  const toolCallId = acpToolCallId(update);
  return isAcpArtifactWriteLabel(update) || (toolCallId ? writeToolCallIds.has(toolCallId) : false);
}
/** Tool names that `countNewArtifacts` treats as write/edit operations. */
const ACP_WRITE_OR_EDIT_TOOL_NAMES: ReadonlySet<string> = new Set([
  'Write',
  'create_file',
  'Edit',
  'str_replace_edit',
  'MultiEdit',
  'multi_edit',
]);

/** Extensions that make a dotted title token look like a real file path. */
const ACP_PATH_LIKE_EXTENSIONS: ReadonlySet<string> = new Set([
  'html',
  'htm',
  'css',
  'js',
  'ts',
  'tsx',
  'jsx',
  'mjs',
  'cjs',
  'md',
  'mdx',
  'json',
  'jsonc',
  'yaml',
  'yml',
  'toml',
  'svg',
  'png',
  'jpg',
  'jpeg',
  'gif',
  'webp',
  'avif',
  'ico',
  'mp4',
  'mov',
  'webm',
  'mp3',
  'wav',
  'm4a',
  'pdf',
  'txt',
  'csv',
  'xml',
  'py',
  'go',
  'rs',
  'rb',
  'php',
  'sh',
  'bash',
  'zsh',
  'vue',
  'svelte',
  'astro',
  'scss',
  'less',
  'map',
  'wasm',
]);

/**
 * Returns `true` when `token` looks like a filesystem path rather than a
 * dotted identifier (`Image.open`, `f.read`, `pptx.util`).
 */
export function isAcpPathLikeToken(token: string): boolean {
  const value = token.trim();
  if (!value) return false;
  if (value.startsWith('.') || value.includes('/') || value.includes('\\')) return true;
  const dot = value.lastIndexOf('.');
  if (dot <= 0 || dot === value.length - 1) return false;
  const ext = value.slice(dot + 1).toLowerCase();
  return ACP_PATH_LIKE_EXTENSIONS.has(ext);
}

/**
 * Maps a common ACP `kind` string to a stable Claude-shaped tool name.
 */
function acpToolNameFromKind(kind: string): string | null {
  const token = kind.trim().toLowerCase();
  if (!token) return null;
  if (token === 'edit' || token === 'patch' || token === 'replace' || token === 'update') {
    return 'Edit';
  }
  if (token === 'write' || token === 'create' || token === 'save') return 'Write';
  if (token === 'read') return 'Read';
  if (token === 'execute' || token === 'bash' || token === 'shell' || token === 'terminal') {
    return 'Bash';
  }
  if (token === 'search' || token === 'grep' || token === 'glob') return 'Grep';
  if (token === 'think' || token === 'thought' || token === 'reason' || token === 'reasoning') {
    return 'Think';
  }
  if (token === 'fetch' || token === 'web') return 'Fetch';
  // Title-case unknown kinds for a stable display name.
  return token.charAt(0).toUpperCase() + token.slice(1);
}

/**
 * Derives a tool name from a human `title` when `name`/`kind` are absent.
 */
function acpToolNameFromTitle(title: string): string | null {
  const trimmed = title.trim();
  if (!trimmed) return null;
  if (/\b(?:grep|search|glob)\b/i.test(trimmed)) return 'Grep';
  if (/\b(?:bash|shell|execute|terminal|run)\b/i.test(trimmed)) return 'Bash';
  if (/\bread\b/i.test(trimmed)) return 'Read';
  if (/\b(?:edit|patch|replace)\b/i.test(trimmed)) return 'Edit';
  if (/\b(?:write|create|save|update)\b/i.test(trimmed)) return 'Write';
  const first = trimmed.split(/\s+/)[0];
  if (!first) return null;
  return first.charAt(0).toUpperCase() + first.slice(1);
}

/**
 * Execute-family names that Langfuse treats as partial-redact only (secret+path
 * lexical masking, not full payload replacement). Custom `kind:other` tools must
 * never inherit these labels — a malicious or misconfigured MCP adapter can
 * otherwise place private content in `rawInput` and bypass fail-closed redaction.
 * Keep in sync with `PARTIAL_REDACT_TOOL_NAMES_LOWER` in langfuse-trace.ts.
 */
const ACP_PARTIAL_REDACT_TOOL_NAMES_LOWER: ReadonlySet<string> = new Set([
  'bash',
  'shell',
  'execute',
  'terminal',
]);

/** True when a tool name would enter Langfuse's Bash-like partial-redact allowlist. */
export function isAcpPartialRedactToolName(toolName: string): boolean {
  const normalized = toolName.trim().toLowerCase();
  if (!normalized) return false;
  return ACP_PARTIAL_REDACT_TOOL_NAMES_LOWER.has(normalized);
}

/**
 * Sanitizes an ACP custom/adapter tool name before it enters the transcript.
 *
 * Kind `other` tools may ship free-text `name` values that embed paths, URLs,
 * tokens, or other user-specific strings. Those names flow into tool_use events
 * and then into Langfuse span labels / toolName metadata (even when content
 * telemetry is off). Only identifier-like names are kept; everything else
 * collapses to the opaque family label `Other`. Langfuse additionally
 * canonicalizes non-allowlisted names at the telemetry boundary.
 *
 * Callers that resolve names without a recognized execute-family kind
 * (missing kind, kind:other, unknown kinds) must also reject Bash-like
 * partial-redact labels via `isAcpPartialRedactToolName` so custom tools
 * cannot impersonate the sole non-fail-closed family.
 */
export function sanitizeAcpCustomToolName(raw: string): string {
  const trimmed = raw.trim();
  if (!trimmed) return 'Other';
  // Paths, URLs, free-text titles, and overlong strings are never safe labels.
  if (
    trimmed.includes('/') ||
    trimmed.includes('\\') ||
    trimmed.includes('://') ||
    /\s/.test(trimmed) ||
    trimmed.length > 64
  ) {
    return 'Other';
  }
  // Identifier-like only (snake_case, TitleCase, mcp__server__tool, …).
  if (!/^[A-Za-z][A-Za-z0-9_.-]*$/.test(trimmed)) {
    return 'Other';
  }
  return trimmed;
}

/**
 * Maps an ACP adapter `toolCallId` to a transcript/telemetry-safe id.
 *
 * Adapters may embed user paths or secrets in toolCallId (for example
 * `read:/home/alice/.env`, `sk-proj-…`, `ghp_…`, or a JWT). Those values
 * would otherwise flow into tool_use/tool_result events, then into Langfuse
 * span ids and `metadata.toolCallId`. Every non-empty adapter id is replaced
 * with a stable opaque hash so identifier-shaped secrets cannot leak even
 * when they contain no path characters. Session-local maps may still key
 * off the raw id for frame correlation.
 */
export function acpTelemetryToolCallId(raw: string): string {
  const trimmed = raw.trim();
  if (!trimmed) return 'acp_empty';
  return `acp_${createHash('sha256').update(trimmed, 'utf8').digest('hex').slice(0, 24)}`;
}

/**
 * Resolves a stable Claude-shaped tool name from an ACP tool-call update.
 * Trusted ACP `kind` wins over both explicit `name` and title heuristics when
 * the kind is a known tool family (so `kind: read` + `name: read_file` or
 * title "update …" stays Read). That keeps content-tool redaction and analytics
 * families aligned with Langfuse's canonical name set. Kind `other` is the
 * exception: it is recognized for stickiness but is not a family, so an
 * explicit identifier-like name still wins there for UI/transcript — except
 * Bash-like partial-redact labels, which collapse to `Other` so custom MCP
 * tools cannot bypass Langfuse fail-closed payload redaction. The same rule
 * applies when `kind` is missing: a bare `name: "Bash"` (or Bash-like title)
 * must not unlock partial redaction without a recognized execute-family kind.
 * Untrusted free-text names (paths, tokens, titles) are collapsed to `Other`
 * before the event is emitted so Langfuse span labels cannot carry
 * user-specific strings. Payloads for unknown tools still fail closed in
 * Langfuse (`shouldFullyRedactToolPayload`). Write-label override to Write/Edit
 * applies only when there is no recognized non-write kind, so
 * `countNewArtifacts` keeps working for title-only write frames.
 */
export function acpToolName(update: JsonObject): string {
  const kindRaw = typeof update.kind === 'string' ? update.kind.trim() : '';
  const kindToken = kindRaw.toLowerCase();
  const recognizedKind = kindRaw ? isAcpRecognizedKind(kindRaw) : false;
  const kindName = kindRaw ? acpToolNameFromKind(kindRaw) : null;
  // "other" is a valid ACP kind for custom tools, not a canonical family.
  const kindIsCanonicalFamily = recognizedKind && kindToken !== 'other';

  let name: string | null = null;
  if (kindIsCanonicalFamily && kindName) {
    // Canonical kind wins over explicit noncanonical names (read_file, etc.).
    // Content-tool redaction keys off stable Claude-shaped families; keeping
    // adapter-local names would skip the known-content path (unknown names
    // still fail closed in Langfuse, but canonical families stay precise).
    // Execute-family kinds are the only path that may emit Bash (partial-redact).
    name = kindName;
  } else if (typeof update.name === 'string' && update.name.trim()) {
    // kind:other / missing kind / unknown kind: keep only identifier-like
    // adapter names. Paths, tokens, and free text collapse to Other before
    // the event is emitted.
    name = sanitizeAcpCustomToolName(update.name);
    // Fail closed: without a recognized execute-family kind, never claim
    // Bash/shell/execute/terminal. Those names unlock Langfuse partial-redact
    // (lexical masking only); unclassified custom tools (no kind, kind:other)
    // can put arbitrary private content in rawInput.
    if (isAcpPartialRedactToolName(name)) {
      name = 'Other';
    }
  } else if (recognizedKind && kindName) {
    // kind:other without an explicit name (title-case "Other"), or remaining
    // recognized kinds without a preferred name.
    name = kindName;
  } else if (typeof update.title === 'string' && update.title.trim()) {
    const fromTitle = acpToolNameFromTitle(update.title);
    // Title heuristics can still surface path-like first tokens; sanitize.
    name = fromTitle ? sanitizeAcpCustomToolName(fromTitle) : null;
    // Same fail-closed rule for title-derived Bash labels without execute kind
    // (missing kind, kind:other, or any non-canonical-family path).
    if (name && isAcpPartialRedactToolName(name)) {
      name = 'Other';
    }
  } else if (kindName) {
    name = kindName;
  }
  if (!name) name = 'Tool';

  // Write-label override: only when kind is absent/unrecognized, or is already
  // a write/edit family kind. Never turn kind:read into Write because the title
  // contains "update".
  if (isAcpArtifactWriteLabel(update) && !ACP_WRITE_OR_EDIT_TOOL_NAMES.has(name)) {
    if (recognizedKind && !isAcpWriteEditKind(kindRaw)) {
      return name;
    }
    const label = [
      typeof update.title === 'string' ? update.title : '',
      typeof update.name === 'string' ? update.name : '',
      typeof update.kind === 'string' ? update.kind : '',
    ].join(' ');
    if (/\b(?:edit|patch|replace)\b/i.test(label)) return 'Edit';
    return 'Write';
  }
  return name;
}

/**
 * Builds a Claude-shaped tool input object from an ACP tool-call update.
 * Starts from `rawInput` when present, attaches `file_path` when a real path
 * is available, and never fabricates a path from `toolCallId`.
 */
export function acpToolInput(update: JsonObject): Record<string, unknown> {
  const rawInput = asObject(update.rawInput);
  const input: Record<string, unknown> = rawInput ? { ...rawInput } : {};
  const path = acpArtifactWritePath(update);
  if (path) {
    input.file_path = path;
  }
  if (Object.keys(input).length === 0) {
    if (typeof update.title === 'string' && update.title.trim()) {
      return { title: update.title.trim() };
    }
    return {};
  }
  return input;
}

/**
 * Extracts tool-result text from an ACP terminal tool-call update.
 * Prefers `rawOutput`, then text/diff content entries. Truncates large
 * payloads so trace storage stays bounded.
 */
export function acpToolResultContent(update: JsonObject, maxChars = 8000): string {
  const rawOutput = update.rawOutput;
  let text = '';
  if (typeof rawOutput === 'string') {
    text = rawOutput;
  } else if (rawOutput !== undefined && rawOutput !== null) {
    try {
      text = JSON.stringify(rawOutput);
    } catch {
      text = String(rawOutput);
    }
  } else if (Array.isArray(update.content)) {
    const parts: string[] = [];
    for (const entry of update.content) {
      const obj = asObject(entry);
      if (!obj) {
        if (typeof entry === 'string' && entry) parts.push(entry);
        continue;
      }
      if (typeof obj.text === 'string' && obj.text) {
        parts.push(obj.text);
        continue;
      }
      if (typeof obj.diff === 'string' && obj.diff) {
        parts.push(obj.diff);
        continue;
      }
      // ACP diff entries often carry oldText/newText instead of a unified diff.
      const oldText = typeof obj.oldText === 'string' ? obj.oldText : '';
      const newText = typeof obj.newText === 'string' ? obj.newText : '';
      if (oldText || newText) {
        parts.push(`--- old\n${oldText}\n+++ new\n${newText}`);
        continue;
      }
      const extracted = extractAcpUpdateText(obj);
      if (extracted) parts.push(extracted);
    }
    text = parts.join('\n');
  } else {
    text = extractAcpUpdateText(update) ?? '';
  }
  if (!text) return '';
  if (text.length <= maxChars) return text;
  return `${text.slice(0, maxChars)}\n…[truncated]`;
}

/**
 * Execute-family tools whose stdout can contain arbitrary private file content
 * (`cat .env`, dumps of secrets, etc.). Normalized ACP names for these kinds
 * are Claude-shaped `Bash` plus common aliases.
 */
const ACP_EXECUTE_TOOL_NAMES_LOWER: ReadonlySet<string> = new Set([
  'bash',
  'shell',
  'execute',
  'terminal',
]);

/** True when `toolName` is an ACP execute/bash-family tool. */
export function isAcpExecuteToolName(toolName: string): boolean {
  const normalized = toolName.trim().toLowerCase();
  if (!normalized) return false;
  return ACP_EXECUTE_TOOL_NAMES_LOWER.has(normalized);
}

/**
 * Sanitizes ACP tool_result content for the canonical agent transcript.
 *
 * Content tools (Read/Write/…) keep full bodies so the local UI and Langfuse
 * content-tool redactor can each do their job. Execute/Bash is different:
 * Langfuse only applies lexical secret+path masking to Bash, and ACP only
 * started forwarding execute results with the full-transcript change — so a
 * `cat .env` body would ship to telemetry almost intact. Replace raw stdout
 * with a length summary before emit.
 */
export function acpSafeToolResultContent(toolName: string, content: string): string {
  if (!content) return content;
  if (!isAcpExecuteToolName(toolName)) return content;
  return `[REDACTED:acp_bash_output:${content.length}_chars]`;
}

/**
 * Best-effort extraction of a concrete file path from an ACP tool-call update,
 * checking three sources in priority order:
 * 1. `locations` or `content` array entries with a `path` field.
 * 2. `rawInput.path`, `rawInput.file_path`, `rawInput.filename`, or `rawInput.filePath`.
 * 3. A path-like filename token embedded in the human-readable `title` field
 *    (rejects dotted identifiers like `Image.open`).
 *
 * Returns `null` when no concrete path is present. Does not use `toolCallId`
 * as a path — callers decide how to key pathless writes.
 *
 * @param update - A parsed ACP `session/update` params object.
 * @returns An absolute or relative file path string, or `null` when absent.
 */
export function acpArtifactWritePath(update: JsonObject): string | null {
  return acpArtifactWritePathRanked(update)?.path ?? null;
}

/** @module agent-protocol/core
 * Foundation barrel for the agent-protocol module. Re-exports the shared
 * JSON-line stream parser consumed by every protocol adapter (acp/, pi-rpc/).
 */
export { createJsonLineStream } from './json-line-stream.js';

/** @module agent-protocol/core/json-line-stream
 * Streaming JSON-line parser that reassembles pretty-printed and multiline
 * JSON-RPC messages across chunk boundaries. Shared transport used by both the
 * acp/ and pi-rpc/ protocol adapters; this file has no dependencies on any
 * other agent-protocol sibling.
 */

/**
 * Creates a streaming JSON-line parser over a raw byte/string stream.
 * Buffers incoming chunks, splits on newline boundaries, and attempts
 * `JSON.parse` on each line. Accumulates pretty-printed (multiline) JSON across
 * up to 256 lines and 128 kB before abandoning and re-trying the current line
 * as a fresh candidate.
 *
 * Used as the shared ACP transport: both the acp/ and pi-rpc/ adapters call
 * this to decode JSON-RPC frames from a subprocess's stdout.
 *
 * @param onMessage - Called for each successfully parsed JSON value along with
 *   the raw reassembled line string as a second argument.
 * @returns An object with `feed(chunk)` for incremental input and `flush()` to
 *   drain any residual buffered content at stream end.
 */
export function createJsonLineStream(onMessage: (message: unknown, rawLine: string) => void) {
  let buffer = '';
  let pendingJsonLines: string[] = [];

  const emit = (candidate: string): boolean => {
    try {
      onMessage(JSON.parse(candidate), candidate);
      return true;
    } catch {
      return false;
    }
  };

  const pendingCandidate = () => pendingJsonLines.join('\n');

  const startPendingJson = (line: string) => {
    pendingJsonLines = [line];
  };

  const resetPendingJson = () => {
    pendingJsonLines = [];
  };

  // A failed aggregate must never swallow a line that is itself a complete
  // JSON frame. Aggregation is a bounded bet that recent lines form one
  // multiline response; a truncated line ending in value position (e.g.
  // `{"truncated":`) keeps the bet alive because the next complete frame
  // slots into the value hole and stays syntactically plausible. When the
  // bet is lost -- the aggregate turns invalid, outgrows its bounds, or the
  // stream ends -- every absorbed line is settled on its own: standalone
  // frames are delivered, non-JSON lines are dropped. Settled lines do not
  // re-enter aggregation.
  const replayPendingJsonLines = () => {
    const absorbed = pendingJsonLines;
    pendingJsonLines = [];
    for (const line of absorbed) {
      emit(line);
    }
  };

  const handleLine = (line: string) => {
    const trimmed = line.trim();
    if (!trimmed) return;
    if (pendingJsonLines.length > 0) {
      const nextCandidate = `${pendingCandidate()}\n${trimmed}`;
      if (emit(nextCandidate)) {
        resetPendingJson();
        return;
      }
      const state = classifyJsonCandidate(nextCandidate);
      if (
        state === 'incomplete' &&
        nextCandidate.length <= 128_000 &&
        pendingJsonLines.length < 256
      ) {
        pendingJsonLines.push(trimmed);
        return;
      }
      replayPendingJsonLines();
      handleLine(trimmed);
      return;
    }
    if (emit(trimmed)) return;
    // ACP is line-delimited JSON-RPC, but a few bridges have emitted
    // pretty-printed JSON during startup. Keep a bounded aggregate so an
    // otherwise valid multiline initialize response does not get discarded
    // line-by-line and leave the session stuck in spawn pending.
    if (
      (trimmed.startsWith('{') || trimmed.startsWith('[')) &&
      classifyJsonCandidate(trimmed) === 'incomplete'
    ) {
      startPendingJson(trimmed);
    }
  };

  return {
    feed(chunk: string) {
      buffer += chunk;
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';
      for (const line of lines) {
        handleLine(line);
      }
    },
    flush() {
      const trimmed = buffer.trim();
      buffer = '';
      if (trimmed) {
        handleLine(trimmed);
      }
      if (pendingJsonLines.length > 0) {
        if (emit(pendingCandidate())) {
          resetPendingJson();
        } else {
          replayPendingJsonLines();
        }
      }
      // Ignore trailing non-JSON log lines on stdout.
    },
  };
}
/**
 * Incremental JSON completeness classifier used by `createJsonLineStream` to
 * decide whether an accumulating multiline candidate can still resolve into
 * valid JSON.
 *
 * Performs a single-pass character-level parse, tracking object and array
 * frames on a stack. Returns:
 * - `'complete'`   — a syntactically valid, fully closed JSON value.
 * - `'incomplete'` — valid so far but the document is still open (unclosed
 *   strings, objects, or arrays).
 * - `'invalid'`    — an irrecoverable syntax error was encountered.
 *
 * @param value - A string candidate to classify, typically one or more
 *   accumulated stdout lines from an ACP subprocess.
 */
export function classifyJsonCandidate(value: string): 'complete' | 'incomplete' | 'invalid' {
  type Frame =
    | { kind: 'object'; expect: 'keyOrEnd' | 'colon' | 'value' | 'commaOrEnd' }
    | { kind: 'array'; expect: 'valueOrEnd' | 'commaOrEnd' };
  const stack: Frame[] = [];
  let rootComplete = false;

  const afterValue = () => {
    const parent = stack.at(-1);
    if (!parent) {
      rootComplete = true;
      return;
    }
    parent.expect = 'commaOrEnd';
  };

  const closeFrame = (kind: 'object' | 'array'): boolean => {
    const current = stack.pop();
    if (!current || current.kind !== kind) return false;
    afterValue();
    return true;
  };

  const parseString = (start: number): number | null => {
    for (let index = start + 1; index < value.length; index += 1) {
      const char = value[index];
      if (char === '\\') {
        index += 1;
        continue;
      }
      if (char === '"') return index;
    }
    return null;
  };

  const parseLiteral = (start: number, literal: string): number | null | false => {
    for (let offset = 0; offset < literal.length; offset += 1) {
      const char = value[start + offset];
      if (char === undefined) return null;
      if (char !== literal[offset]) return false;
    }
    return start + literal.length - 1;
  };

  const parseNumber = (start: number): number | false => {
    let index = start;
    if (value[index] === '-') index += 1;
    if (value[index] === '0') {
      index += 1;
    } else if (/[1-9]/.test(value[index] ?? '')) {
      while (/[0-9]/.test(value[index] ?? '')) index += 1;
    } else {
      return false;
    }
    if (value[index] === '.') {
      index += 1;
      if (!/[0-9]/.test(value[index] ?? '')) return false;
      while (/[0-9]/.test(value[index] ?? '')) index += 1;
    }
    if (value[index] === 'e' || value[index] === 'E') {
      index += 1;
      if (value[index] === '+' || value[index] === '-') index += 1;
      if (!/[0-9]/.test(value[index] ?? '')) return false;
      while (/[0-9]/.test(value[index] ?? '')) index += 1;
    }
    return index - 1;
  };

  const parseValue = (index: number): number | null | false => {
    const char = value[index];
    if (char === '"') {
      const end = parseString(index);
      if (end === null) return null;
      afterValue();
      return end;
    }
    if (char === '{') {
      stack.push({ kind: 'object', expect: 'keyOrEnd' });
      return index;
    }
    if (char === '[') {
      stack.push({ kind: 'array', expect: 'valueOrEnd' });
      return index;
    }
    if (char === 't') {
      const end = parseLiteral(index, 'true');
      if (end === false || end === null) return end;
      afterValue();
      return end;
    }
    if (char === 'f') {
      const end = parseLiteral(index, 'false');
      if (end === false || end === null) return end;
      afterValue();
      return end;
    }
    if (char === 'n') {
      const end = parseLiteral(index, 'null');
      if (end === false || end === null) return end;
      afterValue();
      return end;
    }
    if (char === '-' || /[0-9]/.test(char ?? '')) {
      const end = parseNumber(index);
      if (end === false) return false;
      afterValue();
      return end;
    }
    return false;
  };

  for (let index = 0; index < value.length; index += 1) {
    const char = value[index];
    if (char === undefined) break;
    if (/\s/.test(char)) continue;

    const current = stack.at(-1);
    if (!current) {
      if (rootComplete) return 'invalid';
      const end = parseValue(index);
      if (end === false) return 'invalid';
      if (end === null) return 'incomplete';
      index = end;
      continue;
    }

    if (current.kind === 'object') {
      if (current.expect === 'keyOrEnd') {
        if (char === '}') {
          if (!closeFrame('object')) return 'invalid';
          continue;
        }
        if (char !== '"') return 'invalid';
        const end = parseString(index);
        if (end === null) return 'incomplete';
        current.expect = 'colon';
        index = end;
        continue;
      }
      if (current.expect === 'colon') {
        if (char !== ':') return 'invalid';
        current.expect = 'value';
        continue;
      }
      if (current.expect === 'value') {
        const end = parseValue(index);
        if (end === false) return 'invalid';
        if (end === null) return 'incomplete';
        index = end;
        continue;
      }
      if (char === '}') {
        if (!closeFrame('object')) return 'invalid';
        continue;
      }
      if (char !== ',') return 'invalid';
      current.expect = 'keyOrEnd';
      continue;
    }

    if (current.expect === 'valueOrEnd') {
      if (char === ']') {
        if (!closeFrame('array')) return 'invalid';
        continue;
      }
      const end = parseValue(index);
      if (end === false) return 'invalid';
      if (end === null) return 'incomplete';
      index = end;
      continue;
    }
    if (char === ']') {
      if (!closeFrame('array')) return 'invalid';
      continue;
    }
    if (char !== ',') return 'invalid';
    current.expect = 'valueOrEnd';
  }

  return rootComplete && stack.length === 0 ? 'complete' : 'incomplete';
}

/** @module agent-protocol/dsh-profile/frames
 * Runtime validation for the versioned profile protocol. Validation messages
 * deliberately name fields but never include field values or raw frames.
 */
import {
  DSH_PROFILE_PROTOCOL_VERSION,
  DSH_PROFILE_RUNTIME,
  type DshProfileCapabilities,
  type DshProfileHostCommand,
  type DshProfileRuntimeFrame,
} from './types.js';

type JsonObject = Record<string, unknown>;

function objectValue(value: unknown, label: string): JsonObject {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`${label} must be an object`);
  }
  return value as JsonObject;
}

function stringField(value: JsonObject, field: string, optional = false): string | undefined {
  const found = value[field];
  if (found === undefined && optional) return undefined;
  if (typeof found !== 'string' || found.length === 0) {
    throw new Error(`${field} must be a non-empty string`);
  }
  return found;
}

function booleanField(value: JsonObject, field: string): boolean {
  const found = value[field];
  if (typeof found !== 'boolean') throw new Error(`${field} must be a boolean`);
  return found;
}

function finiteNonNegativeNumber(value: JsonObject, field: string, optional = false): number | undefined {
  const found = value[field];
  if (found === undefined && optional) return undefined;
  if (typeof found !== 'number' || !Number.isFinite(found) || found < 0) {
    throw new Error(`${field} must be a finite non-negative number`);
  }
  return found;
}

function assertVersion(value: JsonObject): void {
  if (value.v !== DSH_PROFILE_PROTOCOL_VERSION) {
    throw new Error(`v must equal ${DSH_PROFILE_PROTOCOL_VERSION}`);
  }
}

function capabilitiesField(value: JsonObject): DshProfileCapabilities {
  const capabilities = objectValue(value.capabilities, 'capabilities');
  if (
    capabilities.session_resume !== true ||
    capabilities.session_cancel !== true ||
    capabilities.structured_events !== true
  ) {
    throw new Error('capabilities must include required generation-1 features');
  }
  return capabilities as DshProfileCapabilities;
}

function assertIdentityFrame(value: JsonObject): void {
  if (value.runtime !== DSH_PROFILE_RUNTIME) {
    throw new Error(`runtime must equal ${DSH_PROFILE_RUNTIME}`);
  }
  if (value.protocol_version !== DSH_PROFILE_PROTOCOL_VERSION) {
    throw new Error(`protocol_version must equal ${DSH_PROFILE_PROTOCOL_VERSION}`);
  }
  stringField(value, 'plugin_version');
  capabilitiesField(value);
}

function assertRequestFrame(value: JsonObject): void {
  stringField(value, 'request_id');
}

function assertWireError(value: unknown): void {
  const error = objectValue(value, 'error');
  stringField(error, 'code');
  stringField(error, 'message');
}

export function parseDshProfileRuntimeFrame(value: unknown): DshProfileRuntimeFrame {
  const frame = objectValue(value, 'frame');
  assertVersion(frame);
  const type = stringField(frame, 'type');
  switch (type) {
    case 'probe':
    case 'ready':
      assertIdentityFrame(frame);
      break;
    case 'session':
      assertRequestFrame(frame);
      stringField(frame, 'session_id');
      booleanField(frame, 'resumed');
      break;
    case 'thinking':
    case 'text':
      assertRequestFrame(frame);
      if (typeof frame.content !== 'string') throw new Error('content must be a string');
      break;
    case 'tool_call':
      assertRequestFrame(frame);
      stringField(frame, 'call_id');
      stringField(frame, 'name');
      if (typeof frame.arguments !== 'string') throw new Error('arguments must be a string');
      break;
    case 'tool_result':
      assertRequestFrame(frame);
      stringField(frame, 'call_id');
      stringField(frame, 'name');
      if (typeof frame.output !== 'string') throw new Error('output must be a string');
      booleanField(frame, 'is_error');
      break;
    case 'usage':
      assertRequestFrame(frame);
      stringField(frame, 'provider');
      stringField(frame, 'model');
      finiteNonNegativeNumber(frame, 'input_tokens');
      finiteNonNegativeNumber(frame, 'output_tokens');
      finiteNonNegativeNumber(frame, 'cache_read_tokens', true);
      finiteNonNegativeNumber(frame, 'cache_write_tokens', true);
      break;
    case 'result': {
      assertRequestFrame(frame);
      if (!['completed', 'cancelled', 'failed'].includes(String(frame.status))) {
        throw new Error('status must be completed, cancelled, or failed');
      }
      stringField(frame, 'session_id');
      stringField(frame, 'output', true);
      stringField(frame, 'stop_reason', true);
      booleanField(frame, 'resume_rejected');
      if (frame.error !== undefined) assertWireError(frame.error);
      if (frame.status === 'failed' && frame.error === undefined) {
        throw new Error('failed result must include error');
      }
      break;
    }
    case 'protocol_error':
      stringField(frame, 'request_id', true);
      stringField(frame, 'code');
      stringField(frame, 'message');
      break;
    default:
      throw new Error('type is not supported by protocol generation 1');
  }
  return frame as DshProfileRuntimeFrame;
}

export function parseDshProfileHostCommand(value: unknown): DshProfileHostCommand {
  const command = objectValue(value, 'command');
  assertVersion(command);
  const type = stringField(command, 'type');
  assertRequestFrame(command);
  if (type === 'cancel') return command as DshProfileHostCommand;
  if (type !== 'execute') {
    throw new Error('type is not a supported host command');
  }
  stringField(command, 'cwd');
  if (typeof command.prompt !== 'string') throw new Error('prompt must be a string');
  stringField(command, 'resume_session_id', true);
  stringField(command, 'reasoning_effort', true);
  if (!Array.isArray(command.mcp_servers)) throw new Error('mcp_servers must be an array');
  if (command.model !== undefined) {
    const model = objectValue(command.model, 'model');
    stringField(model, 'provider');
    stringField(model, 'id');
  }
  return command as DshProfileHostCommand;
}

/** @module agent-protocol/dsh-profile */
export * from './types.js';
export { parseDshProfileHostCommand, parseDshProfileRuntimeFrame } from './frames.js';
export { parseDshProfileModelsOutput, parseDshProfileProbeOutput } from './probe.js';
export { attachDshProfileSession } from './session.js';
export {
  DEFAULT_DSH_PROFILE_MAX_FRAME_BYTES,
  createDshProfileJsonlStream,
} from './stream.js';

/** @module agent-protocol/dsh-profile/probe */
import { parseDshProfileRuntimeFrame } from './frames.js';
import type {
  DshProfileModelCatalogEntry,
  DshProfileProbeFrame,
} from './types.js';

export function parseDshProfileProbeOutput(stdout: string): DshProfileProbeFrame {
  const lines = stdout.split(/\r?\n/u).filter((line) => line.trim().length > 0);
  if (lines.length !== 1) {
    throw new Error('DeepSeek Harness profile probe must emit exactly one frame.');
  }
  let value: unknown;
  try {
    value = JSON.parse(lines[0] ?? '') as unknown;
  } catch {
    throw new Error('DeepSeek Harness profile probe emitted malformed JSON.');
  }
  const frame = parseDshProfileRuntimeFrame(value);
  if (frame.type !== 'probe') {
    throw new Error('DeepSeek Harness profile probe emitted the wrong frame type.');
  }
  return frame;
}

export function parseDshProfileModelsOutput(stdout: string): DshProfileModelCatalogEntry[] | null {
  const lines = stdout.split(/\r?\n/u).filter((line) => line.trim().length > 0);
  if (lines.length !== 1) return null;
  let value: unknown;
  try {
    value = JSON.parse(lines[0] ?? '') as unknown;
  } catch {
    return null;
  }
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const frame = value as Record<string, unknown>;
  if (
    frame.v !== 1 ||
    frame.type !== 'models' ||
    frame.runtime !== 'open-design' ||
    !Array.isArray(frame.models)
  ) return null;

  const models: DshProfileModelCatalogEntry[] = [];
  const seen = new Set<string>();
  for (const candidate of frame.models) {
    if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) return null;
    const model = candidate as Record<string, unknown>;
    if (
      typeof model.provider !== 'string' || model.provider.length === 0 ||
      typeof model.provider_name !== 'string' || model.provider_name.length === 0 ||
      typeof model.id !== 'string' || model.id.length === 0 ||
      typeof model.name !== 'string' || model.name.length === 0
    ) return null;
    let reasoningOptions: DshProfileModelCatalogEntry['reasoning_options'];
    if (model.reasoning_options !== undefined) {
      if (!Array.isArray(model.reasoning_options)) return null;
      reasoningOptions = [];
      const seenEfforts = new Set<string>();
      for (const candidateEffort of model.reasoning_options) {
        if (!candidateEffort || typeof candidateEffort !== 'object' || Array.isArray(candidateEffort)) return null;
        const effort = candidateEffort as Record<string, unknown>;
        if (
          typeof effort.id !== 'string' || effort.id.length === 0 ||
          typeof effort.name !== 'string' || effort.name.length === 0 ||
          (effort.default !== undefined && typeof effort.default !== 'boolean')
        ) return null;
        if (seenEfforts.has(effort.id)) continue;
        seenEfforts.add(effort.id);
        reasoningOptions.push({
          id: effort.id,
          name: effort.name,
          ...(effort.default === true ? { default: true } : {}),
        });
      }
    }
    const id = `${model.provider}/${model.id}`;
    if (seen.has(id)) continue;
    seen.add(id);
    models.push({
      provider: model.provider,
      provider_name: model.provider_name,
      id: model.id,
      name: model.name,
      ...(reasoningOptions?.length ? { reasoning_options: reasoningOptions } : {}),
    });
  }
  return models.length > 0 ? models : null;
}

/** @module agent-protocol/dsh-profile/session
 * One-run controller for `dsh --profile open-design --stdio`.
 */
import type { ChildProcess } from 'node:child_process';
import { createDshProfileJsonlStream } from './stream.js';
import type {
  DshProfileExecuteCommand,
  DshProfileResultStatus,
  DshProfileRuntimeFrame,
} from './types.js';

export type AttachDshProfileSessionOptions = {
  child: ChildProcess;
  requestId: string;
  prompt: string;
  cwd: string;
  model?: string | null;
  reasoningEffort?: string | null;
  resumeSessionId?: string | null;
  send: (event: string, payload: unknown) => void;
  onReady?: () => void;
  onSession?: () => void;
  onComplete?: () => void;
};

function modelSelection(value: string | null | undefined): { provider: string; id: string } | undefined {
  const normalized = value?.trim();
  if (!normalized || normalized === 'default') return undefined;
  const separator = normalized.indexOf('/');
  if (separator <= 0 || separator === normalized.length - 1) {
    throw new Error('DeepSeek Harness model must use provider/model format.');
  }
  return {
    provider: normalized.slice(0, separator),
    id: normalized.slice(separator + 1),
  };
}

function toolInput(argumentsJson: string): Record<string, unknown> {
  try {
    const value = JSON.parse(argumentsJson) as unknown;
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      return value as Record<string, unknown>;
    }
  } catch {
    // Preserve opaque arguments without echoing them into a protocol error.
  }
  return { raw: argumentsJson };
}

export function attachDshProfileSession({
  child,
  requestId,
  prompt,
  cwd,
  model,
  reasoningEffort,
  resumeSessionId,
  send,
  onReady,
  onSession,
  onComplete,
}: AttachDshProfileSessionOptions) {
  if (!child.stdin || !child.stdout) {
    throw new Error('DeepSeek Harness profile child must expose stdin and stdout.');
  }
  const stdin = child.stdin;
  const stdout = child.stdout;
  const selectedModel = modelSelection(model);
  let ready = false;
  let executeSent = false;
  let sessionId: string | null = null;
  let terminalStatus: DshProfileResultStatus | null = null;
  let fatal = false;
  let aborted = false;
  let finished = false;
  let thinkingStarted = false;
  let ignoredRequestFrames = 0;

  const sendCommand = (command: unknown): boolean => {
    if (stdin.destroyed || !stdin.writable) return false;
    return stdin.write(`${JSON.stringify(command)}\n`);
  };

  const fail = (message: string, code = 'DSH_PROFILE_PROTOCOL_ERROR') => {
    if (finished) return;
    fatal = true;
    finished = true;
    terminalStatus = 'failed';
    send('error', {
      message,
      error: { code, message, retryable: false },
    });
    stdin.end();
  };

  const finish = (status: DshProfileResultStatus) => {
    if (finished) {
      fatal = true;
      return;
    }
    finished = true;
    terminalStatus = status;
    if (thinkingStarted) send('agent', { type: 'thinking_end' });
    stdin.end();
    if (status === 'completed') onComplete?.();
  };

  const sendExecute = () => {
    const command: DshProfileExecuteCommand = {
      v: 1,
      type: 'execute',
      request_id: requestId,
      cwd,
      prompt,
      ...(resumeSessionId ? { resume_session_id: resumeSessionId } : {}),
      ...(selectedModel ? { model: selectedModel } : {}),
      ...(reasoningEffort ? { reasoning_effort: reasoningEffort } : {}),
      mcp_servers: [],
    };
    executeSent = true;
    sendCommand(command);
  };

  const requireSession = (): boolean => {
    if (sessionId) return true;
    fail('DeepSeek Harness profile emitted run content before establishing a session.');
    return false;
  };

  const handleRunFrame = (frame: Exclude<DshProfileRuntimeFrame, { type: 'ready' | 'probe' }>) => {
    if (frame.request_id && frame.request_id !== requestId) {
      ignoredRequestFrames += 1;
      return;
    }
    switch (frame.type) {
      case 'session':
        if (sessionId) {
          fail('DeepSeek Harness profile emitted more than one session frame.');
          return;
        }
        if (resumeSessionId && (!frame.resumed || frame.session_id !== resumeSessionId)) {
          fail('DeepSeek Harness profile resumed a different session.', 'DSH_PROFILE_RESUME_MISMATCH');
          return;
        }
        if (!resumeSessionId && frame.resumed) {
          fail('DeepSeek Harness profile reported an unexpected resumed session.');
          return;
        }
        sessionId = frame.session_id;
        send('agent', { type: 'status', label: 'working', sessionId });
        onSession?.();
        return;
      case 'thinking':
        if (!requireSession()) return;
        if (!thinkingStarted) {
          thinkingStarted = true;
          send('agent', { type: 'thinking_start' });
        }
        if (frame.content) send('agent', { type: 'thinking_delta', delta: frame.content });
        return;
      case 'text':
        if (!requireSession()) return;
        if (frame.content) send('agent', { type: 'text_delta', delta: frame.content });
        return;
      case 'tool_call':
        if (!requireSession()) return;
        send('agent', {
          type: 'tool_use',
          id: frame.call_id,
          name: frame.name,
          input: toolInput(frame.arguments),
        });
        return;
      case 'tool_result':
        if (!requireSession()) return;
        send('agent', {
          type: 'tool_result',
          toolUseId: frame.call_id,
          content: frame.output,
          isError: frame.is_error,
        });
        return;
      case 'usage':
        if (!requireSession()) return;
        send('agent', {
          type: 'usage',
          provider: frame.provider,
          model: frame.model,
          usage: {
            input_tokens: frame.input_tokens,
            output_tokens: frame.output_tokens,
            cached_read_tokens: frame.cache_read_tokens ?? 0,
            cached_write_tokens: frame.cache_write_tokens ?? 0,
            total_tokens: frame.input_tokens + frame.output_tokens,
          },
        });
        return;
      case 'protocol_error':
        fail('DeepSeek Harness profile reported a protocol error.', frame.code);
        return;
      case 'result':
        if (resumeSessionId && frame.resume_rejected) {
          if (frame.session_id !== resumeSessionId) {
            fail('DeepSeek Harness profile rejected a different session.', 'DSH_PROFILE_RESUME_MISMATCH');
            return;
          }
          fail('DeepSeek Harness could not resume the saved session.', frame.error?.code ?? 'DSH_PROFILE_RESUME_REJECTED');
          return;
        }
        if (!sessionId && frame.status === 'failed') {
          fail(frame.error?.message ?? 'DeepSeek Harness profile could not start a session.', frame.error?.code);
          return;
        }
        if (!requireSession()) return;
        if (frame.session_id !== sessionId) {
          fail('DeepSeek Harness profile terminal result changed the session id.', 'DSH_PROFILE_SESSION_MISMATCH');
          return;
        }
        if (frame.status === 'failed') {
          fail(frame.error?.message ?? 'DeepSeek Harness profile run failed.', frame.error?.code);
          return;
        }
        if (frame.status === 'cancelled' && !aborted) {
          fail('DeepSeek Harness profile cancelled a run that OpenDesign did not cancel.');
          return;
        }
        finish(frame.status);
        return;
    }
  };

  const parser = createDshProfileJsonlStream({
    onFrame(frame) {
      if (finished) {
        fatal = true;
        return;
      }
      if (!ready) {
        if (frame.type !== 'ready') {
          fail('DeepSeek Harness profile did not begin with a ready frame.');
          return;
        }
        ready = true;
        onReady?.();
        if (aborted) {
          finish('cancelled');
          return;
        }
        sendExecute();
        return;
      }
      if (frame.type === 'ready' || frame.type === 'probe') {
        fail('DeepSeek Harness profile emitted an unexpected identity frame.');
        return;
      }
      handleRunFrame(frame);
    },
    onError(error) {
      fail(error.message, error.code);
    },
  });

  stdout.on('data', (chunk: Buffer | string) => parser.feed(chunk));
  stdout.on('end', () => {
    parser.flush();
    if (!finished) fail('DeepSeek Harness profile exited without a terminal result.', 'DSH_PROFILE_MISSING_RESULT');
  });

  return {
    abort() {
      if (finished || aborted) return;
      aborted = true;
      sendCommand({ v: 1, type: 'cancel', request_id: requestId });
    },
    hasFatalError() {
      return fatal;
    },
    completedSuccessfully() {
      return terminalStatus === 'completed' && !fatal;
    },
    getDurableSessionId() {
      return sessionId;
    },
    getTerminalStatus() {
      return terminalStatus;
    },
    ignoredRequestFrameCount() {
      return ignoredRequestFrames;
    },
    executeWasSent() {
      return executeSent;
    },
  };
}

/** @module agent-protocol/dsh-profile/stream
 * Strict incremental newline-delimited JSON parser for the OD Harness profile.
 * Unlike the tolerant ACP stream, stdout is a protocol-only channel: malformed
 * or multiline data is fatal and raw content is never repeated in errors.
 */
import { StringDecoder } from 'node:string_decoder';
import { parseDshProfileRuntimeFrame } from './frames.js';
import type {
  DshProfileRuntimeFrame,
  DshProfileStreamError,
  DshProfileStreamErrorCode,
} from './types.js';

export const DEFAULT_DSH_PROFILE_MAX_FRAME_BYTES = 1024 * 1024;

export type DshProfileStreamOptions = {
  onFrame: (frame: DshProfileRuntimeFrame) => void;
  onError: (error: DshProfileStreamError) => void;
  maxFrameBytes?: number;
};

function byteLength(value: string): number {
  return Buffer.byteLength(value, 'utf8');
}

export function createDshProfileJsonlStream({
  onFrame,
  onError,
  maxFrameBytes = DEFAULT_DSH_PROFILE_MAX_FRAME_BYTES,
}: DshProfileStreamOptions) {
  const decoder = new StringDecoder('utf8');
  let buffer = '';
  let line = 0;
  let failed = false;

  const fail = (code: DshProfileStreamErrorCode, message: string, errorLine: number) => {
    if (failed) return;
    failed = true;
    buffer = '';
    onError({ code, message, line: errorLine });
  };

  const handleLine = (rawLine: string) => {
    line += 1;
    const candidate = rawLine.endsWith('\r') ? rawLine.slice(0, -1) : rawLine;
    if (candidate.trim().length === 0) return;
    if (byteLength(candidate) > maxFrameBytes) {
      fail('DSH_PROFILE_FRAME_TOO_LARGE', 'DeepSeek Harness profile emitted an oversized frame.', line);
      return;
    }
    let parsed: unknown;
    try {
      parsed = JSON.parse(candidate) as unknown;
    } catch {
      fail('DSH_PROFILE_MALFORMED_FRAME', 'DeepSeek Harness profile emitted malformed JSON.', line);
      return;
    }
    try {
      onFrame(parseDshProfileRuntimeFrame(parsed));
    } catch (error) {
      const detail = error instanceof Error ? error.message : 'frame validation failed';
      fail('DSH_PROFILE_INVALID_FRAME', `DeepSeek Harness profile emitted an invalid frame: ${detail}.`, line);
    }
  };

  const drain = () => {
    let newline = buffer.indexOf('\n');
    while (!failed && newline >= 0) {
      const current = buffer.slice(0, newline);
      buffer = buffer.slice(newline + 1);
      handleLine(current);
      newline = buffer.indexOf('\n');
    }
    if (!failed && byteLength(buffer) > maxFrameBytes) {
      fail('DSH_PROFILE_FRAME_TOO_LARGE', 'DeepSeek Harness profile emitted an oversized frame.', line + 1);
    }
  };

  return {
    feed(chunk: string | Uint8Array) {
      if (failed) return;
      buffer += typeof chunk === 'string' ? chunk : decoder.write(Buffer.from(chunk));
      drain();
    },
    flush() {
      if (failed) return;
      buffer += decoder.end();
      if (buffer.length === 0) return;
      if (buffer.trim().length === 0) {
        buffer = '';
        return;
      }
      // A final complete JSON value without a newline is accepted because EOF
      // is an unambiguous frame boundary. Incomplete/multiline content fails.
      const residual = buffer;
      buffer = '';
      handleLine(residual);
    },
    failIfIncomplete() {
      if (failed || buffer.length === 0 || buffer.trim().length === 0) return;
      fail('DSH_PROFILE_TRUNCATED_FRAME', 'DeepSeek Harness profile ended with a truncated frame.', line + 1);
    },
    hasFailed() {
      return failed;
    },
  };
}

/** @module agent-protocol/dsh-profile/types
 * Generation-1 wire contract for the OpenDesign DeepSeek Harness profile.
 * The user's official `dsh` owns the runtime; this protocol is the thin stdio
 * seam exposed by the installed `open-design` profile bundle.
 */

export const DSH_PROFILE_PROTOCOL_VERSION = 1 as const;
export const DSH_PROFILE_RUNTIME = 'open-design' as const;
export const DSH_PROFILE_NAME = 'open-design' as const;

